WITH payload AS (SELECT $archive_payload$[{"id":"7a1a7194-256d-5831-9886-441f1d932a33","document_type":"judgment","category":"judicial","subcategory":"general","title":"دية -قتل خطأ -إقرار املدعى عليه بالقتل اخلطأ يوجب احلكم عليه بالدية وإفهامه بأن له الرجوع عن عاقلته -كفارة القتل اخلطأ -نصيب القاصر غير السعودي يسلم لوليه املخول له باالستالم -رفع احلكم حملكمة الاستئناف لوجود قاصر .","document_number":"33377046","case_number":"33241066","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بنجران","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/8/12","year":"1434","subject":"دية -قتل خطأ -إقرار املدعى عليه بالقتل اخلطأ يوجب احلكم عليه بالدية وإفهامه بأن له الرجوع عن عاقلته -كفارة القتل اخلطأ -نصيب القاصر غير السعودي يسلم لوليه املخول له باالستالم -رفع احلكم حملكمة الاستئناف لوجود قاصر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/8/12 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪33377046 :‬‬\n                         ‫َر ْق ُم الدعوى‪33241066 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 3423755‬تاريخه‪1434/1/26 :‬هـ‬\n\n\n      ‫ديــة‪ -‬قتــل خطــأ ‪ -‬إقــرار املدعــى عليــه بالقتــل اخلطــأ يوجــب احلكــم‬\n      ‫عليــه بالديــة وإفهامــه بــأن لــه الرجــوع عــن عاقلتــه‪ -‬كفــارة القتــل‬\n      ‫اخلطــأ ‪ -‬نصيــب القاصــر غيــر الســعودي يســلم لوليــه املخــول لــه‬\n             ‫باالســتالم ‪ -‬رفــع احلكــم حملكمــة االســتئناف لوجــود قاصــر ‪.‬‬\n\n\n\n\n      ‫‪ -1‬قولــه تعالــى ‪ ( :‬ومــن قتــل مؤمنــا خطــأ فتحريــر رقبــة مؤمنــة وديــة‬\n                                                                 ‫مســلمة الــى اهلــه ) ‪.‬‬\n      ‫‪ -2‬مــا رواه عمــرو بــن العــاص رضــى اهلل عنــه أن رســول اهلل صلــى اهلل‬\n      ‫عليــه وســلم قضــى أن مــن قتــل خطــأ فديتــه مائــة مــن اإلبــل‪ ،‬أخرجــه‬\n                                                                ‫أبــوداود وابــن ماجــه ‪.‬‬\n      ‫‪ -3‬قولــه صلــى اهلل عليــه وســلم ‪ ( :‬أحلقــوا الفرائــض بأهلهــا فمــا بقــى‬\n                                                               ‫فألولــى رجــل ذكــر )‪.‬‬\n      ‫‪ -4‬األمــر الســامي رقــم ‪ 43108‬يف ‪1432/10/2‬ه ـ املتضمــن تقديــره ديــة‬\n                                              ‫قتــل اخلطــأ بثالثمائــة ألــف ريــال ‪.‬‬\n\n\n\n\n‫‪279‬‬\n\f‫ادعــى وكيــل ورثــة أحــد املقيمــن علــى املدعــى عليــه بأنــه دهــس‬\n‫بســيارته مــورث موكليــه أثنــاء عبــوره الشــارع العــام ممــا أدى إلــى‬\n‫وفاته‪،‬حيــث إن الدهــس عــن طريــق اخلطــأ طلــب املدعــى إلــزام املدعــى‬\n‫عليــه بدفــع ديــة قتــل اخلطــأ ‪ -‬أقــر املدعــى عليــه مبــا جــاء يف الدعــوى‪،‬‬\n‫صــدر احلكــم بإلــزام املدعــى عليــه بدفــع ديــة قتــل اخلطــأ للمدعــن كل‬\n‫حســب نصيبــه الشــرعي مــن الديــة‪ ،‬إفهــام املدعــى عليــه بــأن لــه الرجــوع‬\n‫عاقلتــه إن صدقتــه ‪ -‬افهــام املدعــى عليــه بــان عليــه كفــارة قتــل اخلطــأ‪،‬‬\n‫قــرر الطرفــان القناعــة باحلكــم‪ ،‬مت رفــع املعاملــة حملكمــة االســتئناف‬\n‫لوجــود القاصــرة‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪ -‬جــرى‬\n       ‫تســليم كامــل الديــة للمدعــي وكالــة وبذلــك انتهــت القضيــة ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n‫أنــا ‪ ...‬القاضــي باحملكمــة العامــة بنجــران وبنــاء علــى املعاملــة احملالــة‬\n‫لنــا مــن فضيلــة رئيــس احملكمــة العامــة بنجــران برقــم ‪33241066‬‬\n‫وتاريــخ ‪1433/4/6‬ه ـ واملقيــدة باحملكمــة العامــة برقــم ‪33644911‬‬\n‫وتاريــخ ‪1433/4/6‬ه ـ ففــي يــوم االثنــن املوافــق ‪1433/6/30‬ه ـ حضــر‬\n‫‪ ...‬مصــري اجلنســية مبوجــب االقامــة رقــم ‪ ...‬بصفتــه وكيــا عــن ورثــة‬\n‫‪ ...‬مبوجــب الــوكاالت املرفقــه معــه لورثــة ‪ ...‬املنحصــر ارثــه يف كل مــن‬\n‫زوجتــه ‪ ...‬ووالدتــه ‪ ...‬ووالــده ‪ ...‬وابنتــه ‪ ...‬القاصــرة ســن ًا مبوجــب اعــام‬\n‫الوراثــه الصــادر مــن محكمــة بنــدر شــبني الكــوم لشــئون االســرة‬\n\n                                                                                       ‫‪280‬‬\n\f      ‫برقــم ‪ 36768‬وتاريــخ ‪ 2011/10/19‬واملصــادق عليهــا مــن اجلهــات‬\n      ‫الرســمية مدعي ـ ًا علــى احلاضــر معــه يف مجلــس احلكــم ‪ ... ...‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬وبعــد االطــاع علــى الــوكاالت‬\n      ‫املرفقــة معــه وجدتهــا ال تخولــه حــق املرافعــة وال املدافعــة لــدى احملاكــم‬\n      ‫فأفهمتــه بإكمــال الناقــص ورفعــت اجللســة لذلــك ويف يــوم اإلثنــن‬\n      ‫املوافــق‪ 1433/08/12‬ه ـ حضــر املدعــي وكالــة واملدعــى عليــه اصالــة‬\n      ‫املدونــة هويتهمــا ســابقا وباالطــاع علــى وكاالت الوكيــل وجدتــه‬\n      ‫وكيــا عــن ‪ ...‬و‪ ...‬و‪ ...‬مبوجــب الوكالــة الصــادرة مــن جمهوريــة مصــر‬\n      ‫برقــم ‪ 2507/1112‬واملصــادق عليهــا مــن اجلهــات الرســمية والتــي تخولــه‬\n      ‫حــق املطالبــة بالديــة وتســليم اللوائــح االعتراضيــة وغيــر ذلــك وبصفتــه‬\n      ‫وكيــا عــن ‪ ...‬بصفتــه ولي ـ ًا علــى القاصــر ‪ ...‬ومبوجــب الوكالــة‬\n      ‫الصــادرة مــن جمهوريــة مصــر برقــم ‪ 560320‬وتاريــخ ‪2012/05/28‬‬\n      ‫والتــي تخولــه حــق املرافعــة مــن احملاكــم الســعودية واالقــرار واالنــكار‬\n      ‫وتســليم اللوائــح االعتراضيــة واالســتالم والتســليم بالشــيكات اخلاصــة‬\n      ‫بالقاصــر دون صرفهــا وقــد ادعــى املدعــي وكالــة علــى املدعــى عليــه‬\n      ‫احلاضــر قائــا يف دعــواه أن مــورث موكلــي كان يقطــع شــارع حــي‬\n      ‫االربعني مبحافظة ‪ ...‬من الشــرق إلى الغرب وأقبل املدعى عليه بســيارة‬\n      ‫مــن نــوع ‪ ...‬خضــراء اللــون موديــل ‪ .....‬حتمــل اللوحــة رقــم ‪ ...‬مســرعا‬\n      ‫متجــه مــن الشــمال الــى اجلنــوب واصطــدم مبــورث موكلــي صدمــة أدت‬\n      ‫إلــى وفاتــه مباشــرة أطلــب الــزام املدعــى عليــه بدفــع الديــة الكاملــة‬\n      ‫ملوكلــي هكــذا ادعــى وبعــرض ماجــاء يف الدعــوى علــى املدعــى عليــه‬\n      ‫صــادق عليــه جملــة وتفصيــا ثــم جــرى االطــاع علــى صفحــة ‪ 7‬مــن دفتــر‬\n      ‫ملــف اجــراءات االســتدالل واملرفــق باملعاملــة ‪ 49‬ووجــدت بهــا اقــرارا مــن‬\n\n\n‫‪281‬‬\n\f‫املدعــى عليــه بصحــة مــا جــاء يف الدعــوى وإقــراره بانــه املتســبب الوحيــد‬\n‫بعــد اهلل عــز وجــل وانــه مقتنــع مبســئولية احلــادث التــي وضعــت عليــه مــن‬\n‫قبــل إدارة املــرور بواقــع مائــة باملائــة وليــس لــه اعتــراض علــى ذلــك وقــد‬\n‫متــت املصادقــة علــى ذلــك االقــرار مــن قبــل القاضــي باحملكمــة العامة ‪...‬‬\n‫وبعرضــه عليــه صــادق عليــه وأكــد قناعتــه بالنســبة وبنــاءا علــى ماتقــدم‬\n‫مــن الدعــوى واالجابــة وملصادقــة الطرفــن علــى النســبة املقــدرة مــن‬\n‫اجلهــات املختصــة وقناعتهمــا بهــا ولقولــه تعالــى ( ومــن قتــل مؤمنـ ًا خطــأ‬\n‫فتحريــر رقبــة مؤمنــة وديــة مســلمة إلــى أهلــه ) اآليــة وملــا رواه عمــرو بــن‬\n‫العــاص رضــي اهلل عنــه أن رســول اهلل صلــى اهلل عليــه وســلم قضــى أن‬\n‫مــن قتــل خطــأ فديتــه مائــة مــن اإلبــل أخرجه ابــو داود وابــن ماجه ولالمر‬\n‫الســامي البرقــي ذي الرقــم ‪ 43108‬وتاريــخ ‪1432/10/02‬ه ـ واملتضمــن‬\n‫تقديــر ديــة قتــل اخلطــأ ثــاث مائــة ألــف ريــال ســعودي والنحصــار ورثــة‬\n‫املتوفــى يف والديــه وزوجتــه وابنتــه ولكــون نصيــب البنــت مــن تركــة‬\n‫املتوفــى النصــف ونصيــب الزوجــة الثمــن ونصيــب االم الســدس ونصيــب‬\n‫االب الســدس فرضــا ولقولــه صلــى اهلل عليــه وســلم ( احلقــوا الفرائــض‬\n‫باهلهــا فمــا بقــي فألولــى رجــل ذكــر ) ولكــون االب أولــى الرجــال‬\n‫الذكــور فيأخــذ الباقــي تعصيبــا وملــا تقــدم كلــه فقــد حكمــت بالــزام‬\n‫املدعــى عليــه ‪ ...‬بدفــع مبلغــا وقــدره اثنــان وســتون الفــا وخمــس مائــة‬\n‫ريــال ســعودي لوالــد القتيــل ‪ ...‬ومبلــغ وقــدره خمســون الــف ريــال ســعودي‬\n‫لوالــدة القتيــل ‪ ...‬ومبلــغ وقــدرة ســبعة وثالثــون الفــا وخمســمائة ريــال‬\n‫ســعودي لزوجــة القتيــل ‪ ...‬ومبلــغ وقــدره مائــة وخمســون الــف ريــال‬\n‫ســعودي البنــة القتيــل القاصــر عــن ســن الرشــد ‪ ... ...‬مبــا تقــدم حكمــت‬\n‫وأفهمــت املدعــى عليــه ان عليــه كفــارة القتــل اخلطــأ كمــا افهمتــه بــان‬\n\n\n                                                                                        ‫‪282‬‬\n\f      ‫لــه الرجــوع علــى العاقلــة ان صدقتــه وبعــرض احلكــم علــى الطرفــن قرر‬\n      ‫املدعــي قناعتــه باحلكــم وقــرر املدعــى عليــه اعتراضــه علــى احلكــم‬\n      ‫واســتعد لتقــدمي الئحــة اعتراضيــة وأفهــم باســتالم نســخة مــن احلكــم يف‬\n      ‫هــذا اليــوم كمــا أفهــم بــأن عليــه ان يســلم الئحتــه االعتراضيــه خــال‬\n      ‫ثالثــن يومــا تبــدأ مــن هــذا اليــوم وأن حقــه يف االعتــراض يســقط اذا‬\n      ‫انتهــت املــدة ولــم يســلم الئحتــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                   ‫محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪ 1433/08/12‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد‬\n      ‫فقــد عــادت املعاملــة مــن محكمــة االســتئناف مبنطقــة عســير برفقهــا‬\n      ‫القــرار الصــادر مــن الدائــرة اجلزائيــة الثالثــة برقــم ‪ 3423755‬وتاريــخ‬\n      ‫‪1434/01/26‬ه ـ ونــص احلاجــة منــه ( وباالطــاع علــى مــا أجــاب‬\n      ‫بــه فضيلتــه وأحلقــه بالصــك وصــورة ضبطــه بنــاء علــى قرارنــا رقــم‬\n      ‫(‪ ) 33441703‬وتاريــخ ‪1433/10/29‬ه ـ تقــررت املوافقــة علــى احلكــم‬\n      ‫بعــد اإلجــراء األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n      ‫وصحبــه وســلم قاضــي اســتئناف ‪ ...‬ختمــه وتوقيعــه قاضــي اســتئناف‬\n      ‫‪ ...‬ختمــه وتوقيعــه رئيــس الدائــرة ‪ ...‬ختمــه وتوقيعــه ) وحتــى ال يخفــى‬\n      ‫جــرى حتريــره وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                      ‫وصحبــه وســلم حــرر يف ‪ 1434/02/16‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد حضــر ‪...‬‬\n      ‫هويتــه ووكالتــه ســابقا وبعــد اإلطــاع على الوكاالت املرصودة ســابقا‬\n      ‫وجدتهــا تخولــه حــق اســتالم الشــيكات واملســتحقات املاليــة فجــرى‬\n      ‫تســليمه الشــيك املســحوب علــى البنــك ‪ ...‬برقــم ‪ ...‬يف ‪1423/09/06‬ه ـ‬\n      ‫مببلــغ وقــدره مائــة ألــف ريــال ســعودي والشــيك املســحوب علــى البنــك‬\n\n\n‫‪283‬‬\n\f‫األهلــي رقــم ‪ ...‬يف ‪1434/10/20‬ه ـ مببلــغ وقــدره مائتــن ألــف ريــال‬\n‫ســعودي وبهــذا تكــون القضيــة منتهيــة وحتــى ال يخفــى جــرى حتريــره‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                  ‫حــرر يف ‪ 1434/11/19‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املـ ــعاملة‬\n‫الــواردة مــن فضيلــة رئيــس الـ ــمحكمة العامــة بنجــران الـ ــمكلف‬\n‫الشيـ ــخ ‪ ..... /‬برقم ‪ ...‬وتـاريـ ــخ ‪1434/1/3‬هـ املرفق بها الصك الصادر‬\n‫مــن فضيل ــته برقــم ‪ 33377046‬وتاريــخ ‪1433/8/12‬ه ـ اخلــاص بدعــوى‬\n‫ورثــة ‪- ... /‬مصــري اجلنســية‪ -‬ضـ ــد ‪ ... /‬يف ( املطالبــة بديــة ) علــى‬\n‫الصفــة املوضحــة يف الصــك املتضمــن حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه وحيــث ســبق دراســة الصــك وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه‬\n‫ـاء علــى قرارنــا رقــم (‪)33441703‬‬     ‫وأحلقــه بالصــك وصــورة ضبطــه بنـ ً‬\n‫وتاريــخ ‪1433/10/29‬ه ـ تقــررت املوافقــة علــى احلكــم بعــد اإلجــراء‬\n‫األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                     ‫‪284‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":279,"source_page_end":284,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"575315ba01b3f7fd97dc9a9f4d605c9faf6d2cef075d915defc900af55cdec42","normalized_text_hash":"54c69fa517ec1b7d80f9ef0abeaf1239d57f5f9f4b56e0dc76f10f45dc4bc25d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p279-33377046"},{"id":"34855fb4-6a63-573e-a6a6-1c206a388c98","document_type":"judgment","category":"judicial","subcategory":"general","title":"دية -حادث مروري -وفاة مورث املدعن -مطالبة بدية قتل خطأ -إدانة املدعى عليه بنسبة خطأ -شهادة معدي تقرير احلادث- إلزام املدعى عليه بدفع دية قتل اخلطأ حسب نسبة اخلطأ املقررة وصرف النظر عن الباقي.","document_number":"34198026","case_number":"33405926","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بجازان","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/27","year":"1434","subject":"دية -حادث مروري -وفاة مورث املدعن -مطالبة بدية قتل خطأ -إدانة املدعى عليه بنسبة خطأ -شهادة معدي تقرير احلادث- إلزام املدعى عليه بدفع دية قتل اخلطأ حسب نسبة اخلطأ املقررة وصرف النظر عن الباقي.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/4/27 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34198026 :‬‬\n                         ‫َر ْق ُم الدعوى‪33405926 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34303182‬تاريخه‪1434/8/23 :‬هـ‬\n\n\n      ‫ديــة ‪ -‬حــادث مــروري‪ -‬وفــاة مــورث املدعــن ‪ -‬مطالبــة بديــة قتــل خطــأ‬\n      ‫‪ -‬إدانــة املدعــى عليــه بنســبة خطــأ‪ -‬شــهادة معــدي تقريــر احلــادث‪-‬‬\n      ‫إلــزام املدعــى عليــه بدفــع ديــة قتــل اخلطــأ حســب نســبة اخلطــأ املقــررة‬\n                                                    ‫وصــرف النظــر عــن الباقــي‪.‬‬\n\n\n\n\n      ‫تعميــم معالــي رئيــس املجلــس األعلــى للقضــاء رقــم ‪/192‬ت يف‬\n      ‫‪ 1432/10/9‬ه ـ املبنــى علــى قــرار مجلــس الــوزراء رقــم ‪ 43108‬يف‬\n      ‫‪1432/10/2‬ه ـ املبنــى علــى قــرار الهيئــة العامــة للمحكمــة العليــا‬\n      ‫املتضمــن إعــادة تقديــر الديــة بحيــث تكــون ديــة قتــل اخلطــأ مبلغــا‬\n                                         ‫قــدره ثالثمائــة ألــف ريــال للرجــل ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي وكالــة بــأن املدعــى عليــه تســبب يف وفــاة مــورث موكليه‬\n      ‫ومــن ضمنهــم قصــار حتــت واليــة املدعــي وكالــة اثــر حــادث مــروري‬\n      ‫وقــد أديــن املدعــى عليــه بنســبة خطــأ ‪ %75‬مبوجــب تقريــر املــرور وقــرر‬\n      ‫املدعــى عــدم قناعتــه بهــذه النســبة وطالــب بإلــزام املدعــى عليــه تســليم‬\n      ‫كامــل ديــة القتــل اخلطــأ مبلغــا قــدرة ثالثمائــة ألــف ريــال ‪، .‬صــادق‬\n      ‫املدعــى عليــه علــى احلــادث ونســبة اخلطــأ وقــرر عــدم موافقتــه تســليم‬\n\n‫‪285‬‬\n\f‫كامــل الديــة‪ ،‬أحضــر ناظــر القضيــة محققــي احلــادث وشــهد كل‬\n‫واحــد منهمــا علــى حصــول احلــادث املشــار إليــه يف الدعــوى وأن نســبة‬\n‫اخلطــأ علــى املدعــى عليــه ‪ %75‬لألســباب املشــار اليهــا يف التقريــر ومت‬\n‫تعديلهمــا شــرعا‪ ،‬مت االطــاع علــى تقريــر املــرور وشــهادة الوفــاة وغيــر‬\n‫ذلــك مــن أوراق املعاملــة‪ ،‬صــدر احلكــم بإلــزام املدعــى عليــه بتســليم‬\n‫املدعــى ديــة قتــل اخلطــأ حســب نســبة اخلطــأ املقــررة عليــه مبلغ ـ ًا قــدره‬\n‫مئتــان وخمســة وعشــرون ألــف ريــال وصــرف النظــر عــن مــا زاد عــن‬\n‫ذلــك‪ ،‬مت إفهــام املدعــى عليــه بكفــارة قتــل اخلطــأ‪ ،‬قــرر الطرفــان‬\n‫القناعــة‪ ،‬مت رفــع املعاملــة حملكمــة االســتئناف لوجــود قصــار‪ ،‬صــدر‬\n                      ‫قــرار محكمــة االســتئناف باملصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ...........‬القاضــي يف احملكمــة العامــة‬\n‫بجــازان وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بجــازان برقــم ‪ 33405926‬وتاريــخ ‪ 1433/06/16‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331115438‬وتاريــخ ‪ 1433/06/14‬ه ـ ففــي يــوم‬\n               ‫األحــد املوافــق‪ 1433/10/22‬ه ـ افتتحــت اجللســة الســاعة‬\n‫‪ 09 : 30‬وفيهــا حضــر‪ ...........‬ســعودي بالســجل رقــم ‪ ...........‬بالوكالــة‬\n‫عــن بعــض ورثــة املتــويف بتاريــخ ‪1432/11/7‬ه ـ املنحصــر أرثــه يف ورثــه‬\n‫وهــم والــده‪ ...........‬ويف والدتــه‪ ...........‬ويف زوجتــه ‪ ...........‬ويف أوالده‬\n‫القاصريــن عــن ســن الرشــد وهــم ‪ ...........‬املولــود يف ‪1432/11/15‬ه ـ و‬\n‫‪ ...........‬املولودة يف ‪1422/1/22‬هـ و ‪ ...........‬املولودة يف ‪1427/1/24‬هـ‬\n‫و‪ ...........‬املولودة يف ‪1420/9/4‬هـ مبوجب صك احلصر رقم ‪3364755‬‬\n\n                                                                                      ‫‪286‬‬\n\f      ‫وتاريــخ ‪1433/2/6‬ه ـ الصــادرة مــن هــذه احملكمــة ووكالــة عــن والــد‬\n      ‫املتوفــى برقــم ‪ 1/3‬وتاريــخ ‪1433/1/1‬ه ـ الصــادرة مــن كتابــة عــدل‬\n      ‫صامطــه وعــن والدتــه املتوفــى برقــم ‪ 1/24‬وتاريــخ ‪1433/1/5‬ه ـ‬\n      ‫الصــادرة مــن عــدل أحــد رفيــدة وعــن زوجتــه املتوفــى برقــم ‪33295‬‬\n      ‫وتاريــخ ‪1433/1/3‬ه ـ الصــادرة مــن عــدل الثانيــة بشــرق الريــاض‬\n      ‫وجميعهــا ال تخولــه حــق إقامــة الدعــوى ولــم يحضــر املدعــى عليــه‬\n      ‫املبلــغ لشــخصه للمــرة األولــى عــن طريــق محضــري اخلصــوم وحيــث أن‬\n      ‫الدعــوى يف ديــة فقــد جــرى إفهــام املدعــي وكالــة بإحضــار وكاالت‬\n      ‫تخولــه املطلــوب إلقامــة الدعــوى وواليــة علــى القصــار أو وكالــه مــن‬\n      ‫الولــي عليهــم إذا كان ذلــك متــاح لــه يف صــك الواليــة وقــررت رفــع‬\n      ‫اجللســة ويف جلســة أخــرى حضــر‪ ...........‬ســعودي بالهويــة الوطنيــة‬\n      ‫ســجل رقــم ‪ ...........‬بالواليــة علــى القصــار ســن ًا أوالد وهــم ‪...........‬‬\n      ‫املولــودة بتاريــخ ‪1422/1/22‬ه ـ و‪ ...........‬املولــودة بتاريــخ ‪1425/9/4‬ه ـ‬\n      ‫و‪ ...........‬املولــودة بتاريــخ ‪1427/10/24‬ه ـ و‪ ...........‬املولــود بتاريــخ‬\n      ‫‪1432/11/15‬ه ـ مبوجــب صــك الواليــة رقــم ‪ 33168436‬وتاريــخ‬\n      ‫‪1433/4/3‬ه ـ الصــادر مــن احملكمــة العامــة بجــازان وبالوكالــة عــن‬\n      ‫و رقــم ‪ 33456894‬وتاريــخ ‪1433/12/20‬ه ـ الصــادرة مــن كتابــة عــدل‬\n      ‫جــازان الثانيــة وعــن رقــم وتاريــخ ‪1433/11/9‬ه ـ الصــادرة مــن كتابــة‬\n      ‫العــدل الثانيــة مــن جنــوب الريــاض وهــؤالء هــم ورثــة املتــويف بتاريــخ‬\n      ‫‪1432/11/7‬ه ـ املنحصــر أرثــة مبوجــب صــك احلصــر الصــادر مــن‬\n      ‫هــذه احملكمــة برقــم ‪ 3364755‬وتاريــخ ‪1433/2/6‬ه ـ يف والــدة ويف‬\n      ‫والدتــه ويف زوجتــه ويف أوالده القاصريــن وحضــر حلضــوره مينــي اجلنســية‬\n      ‫مبوجــب رخصــة اإلقامــة رقــم الصــادرة مــن جــوازات جــازان وأدعــى‬\n\n\n‫‪287‬‬\n\f‫األول قائـ ًـا أن املدعــى عليــه هــذا احلاضــر قــد تســبب يف وفــاة مــورث‬\n‫موكلــي والقصــار الذيــن أنــا ولــي عليهــم املذكوريــن بعاليــة أثــر حــادث‬\n‫تصــادم مــروري بينهمــا علــى طريــق أبــي عريــش األحــد حيــث أن مــورث‬\n‫موكلــي والقصــار كان يقــود ســيارة ‪ .....‬واملدعــى عليــه كان يقــود‬\n‫ســيارة ‪ .....‬وقــد أديــن املدعــى عليــه مــن قبــل مــرور أبــي عريــش بنســبة‬\n‫‪ %75‬إال أننــي غيــر مقتنــع بهــذه النســبة كــون مــن ضمــن الورثــة قصــار ًا‬\n‫اطلــب الــزام املدعــى عليــه بدفــع الديــة كاملــه للورثــة بنســبة ‪%100‬‬\n‫هــذه دعــواي وبعــرض الدعــوى علــى املدعــى عليــه صــادق عليهــا جمل ـ ًة‬\n‫ا وقــال ال أوافــق علــى طلــب املدعــى عليــه بدفــع الديــة كاملــة‬ ‫وتفصي ـ ً‬\n‫بنســبة ‪ %100‬حيــث أن املــرور قــد قــرر أن النســبة التــي ادنــت بهــا ‪%75‬‬\n‫وأنــا موافــق علــى تقريــر املــرور هكــذا أجــاب وبعــرض ذلــك علــى‬\n‫املدعــي قــال أننــي متمســك بالــزام املدعــى عليــه بدفــع الديــة كاملــة‬\n‫بنســبة ‪ %100‬هكــذا قــال وقــد حضــر معــدي تقريــر املــرور ســجل مدنــي‬\n‫رقــم يعمــل برتبــة رقيــب مبــرور و ســجل مدنــي رقــم يعمــل برتبــة رقيــب‬\n‫ا‬ ‫مبــرور أبــي عريــش وقــد شــهد كل واحــد منهمــا علــى انفــراد قائ ـ ً‬\n‫أشــهد هلل أننــي قــد باشــرت احلــادث املــروري الواقــع علــى طريــق أبــو‬\n                                                       ‫عريــش أحــد املســارحة‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬القاضــي يف احملكمــة العامــة‬\n‫بجــازان وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بجــازان برقــم ‪ 33405926‬وتاريــخ ‪ 1433/06/16‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331115438‬وتاريــخ ‪ 1433/06/14‬ه ـ ففــي يــوم‬\n‫الثالثــاء املوافــق‪ 1433/12/21‬ه ـ افتتحــت اجللســة الســاعة العاشــرة‬\n‫والنصــف ولــم يحضــر املدعــي ورثــة ‪ ...........‬وال مــن ينــوب عنهــم ولــم‬\n\n\n                                                                                    ‫‪288‬‬\n\f      ‫يحضــر املدعــى عليــه واســتناد ًا للمــادة ‪ 53‬مــن نظــام املرافعــات فقــد‬\n      ‫قــررت شــطب الدعــوة للمــرة األولــى وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n        ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/12/21‬ه ـ‬\n      ‫الــذي أدى إلــى وفــاة حيــث كان املتــويف يســتقل ســيارة ‪ .....‬واملدعــي‬\n      ‫يســتقل ســيارة ‪ .....‬وقــد أديــن املدعــى عليــه بنســبة ‪ %75‬وذلــك مــن‬\n      ‫مجريــات التحقــق واملعاينــة للموقــع لألســباب اآلتيــة (‪ )1‬الســرعة‬\n      ‫الزائــدة ويــدل لذلــك شــدة التصــادم (‪ )2‬انحرافــه مــن خــط ســيره‬\n      ‫الصحيــح إلــى جهــة اليســار دون تأكــد مــن خلــو الطريــق (‪ )3‬عــدم‬\n      ‫التزامــه املســار الصحيــح قبــل وقــوع احلــادث (‪ )4‬عــدم اليقظــة واالنتبــاه‬\n      ‫(‪ )5‬عــدم تــايف وقــوع احلــادث هــذا مــا شــهد بــه كل وأحــد منهمــا‬\n      ‫وبعــرض الشــاهدين ومــا شــهدا بــه علــى املدعــي قــال أمــا الشــاهدان‬\n      ‫فــا أعرفهمــا وأمــا مــا شــهدا بــه فــا أوافــق عليــه وقــد جــرى تعديــل‬\n      ‫الشــاهدين مــن قبــل كل مــن ســعودي بالســجل رقــم و ســعودي بالســجل‬\n      ‫رقــم حيــث شــهدا قائلــن نشــهد هلل أن الشــاهدين املذكوريــن اعــاه‬\n      ‫عــدل ثقتــان وللدراســة فقــد قــررت رفــع اجللســة ويف جلســة أخــرى حضــر‬\n      ‫املدعــي وكالــة وواليــة وحضــر حلضــوره املدعــى عليــه املرصــودة كافــة‬\n      ‫بياناتهمــا األزمــة اجللســة الســابقة وقــد جــرى اإلطــاع عليهــا هــذه‬\n      ‫اجللســة وبعــد الدراســة قــررت الرجــوع إلــى املعاملــة وقــد جــرى اإلطــاع‬\n      ‫علــى تقريــر احلــادث الصــادر مــن مــرور أبــو عريــش لفــة رقــم (‪)24،25‬‬\n      ‫فوجــد طبق ـ ًا لشــهادة الشــاهدين املرصــودة اجللســة الســابقة كمــا‬\n      ‫جــرى اإلطــاع علــى تقريــر الوفــاة الصــادر مــن مستشــفى امللــك فهــد‬\n      ‫بجــازان لفــة رقــم (‪ )14‬املتضمــن وفــاة بتاريــخ ‪1434/11/7‬ه ـ بإصابــة‬\n      ‫حــادة بالدمــاغ نتيجــة حــادث مــروري كمــا جــرى اإلطــاع علــى القــرار‬\n\n\n‫‪289‬‬\n\f‫الشــرعي رقــم ‪ 3364891‬وتاريــخ ‪1433/4/6‬ه ـ الصــادر مــن جزئيــة‬\n‫جــازان املتضمــن إدانــة املدعــى عليــه بنســبة ‪ %75‬يف احلــق العــام وقــد‬\n‫جــرى إجــراء احلســاب فتبــن أن نصيــب األب هــو ســبعة وثالثــون ألف ـ ًا‬\n‫وخمســمائة ريــال ونصيــب األم هــو ســبعة وثالثــون الفـ ًا وخمســمائة ريــال‬\n‫ونصيــب الزوجــة هــو ثمانيــة وعشــرون الف ـ ًا ومائــة وخمســة وعشــرون‬\n‫ريــا ًال ونصيــب األبــن هــو ثمانيــة وأربعــون الفـ ًا وســبعمائة وخمســون ريــا ًال‬\n‫ونصيــب كل بنــت أربعــة وعشــرون الف ـ ًا وثالثمائــة وخمســة وســبعون‬\n‫ـاء علــى شــهادة‬                                                   ‫ريــا ًال لــذا وبنـ ً‬\n                 ‫ـاء علــى مــا ســلف مــن الدعــوى واإلجابــة وبنـ ً‬\n‫معــدي تقريــر احلــادث املعدلــن شــرع ًا وبعــد إجــراءات احلســاب الشــرعي‬\n‫لنصيــب كل وارث وبعــد اإلطــاع علــى تعميــم معالــي رئيــس املجلــس‬\n‫األعلــى للقضــاء رقــم ‪ /192‬ت وتاريــخ ‪1422/10/9‬ه ـ بخصــوص رفــع‬\n‫ديــة اخلطــأ إلــى ثالثمائــة ألــف ريــال فقــد ألزمــت املدعــى عليــه بــأن يدفــع‬\n‫للورثــة املدعــن ديــة مورثهــم حســب النســبة املقــررة ‪ %75‬مبلــغ وقــدرة‬\n‫مائتــان وخمســة وعشــرون ألــف ريــال يــودع نصيــب القصــار يف بيــت‬\n‫املــال وصرفــت النظــر عمــا زاد عــن هــذه النســبة ممــا ورد يف دعــوى‬\n‫املدعــي وكالــة وواليــة وبذلــك حكمــت وأفهمــت املدعــى عليــه أن عليــه‬\n‫كفــارة قتــل اخلطــأ وهــي عتــق رقبــة مؤمنــة فــإن لــم يجــد فصيــام شــهرين‬\n‫متتابعــن وبعــرض احلكــم علــى الطرفــن قــررا القناعــة ولكــون يف‬\n‫القضيــة قصــار فقــد قــررت رفــع كامــل املعاملــة حملكمــة االســتئناف‬\n‫بعســير وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                               ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/17‬هــ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد‬\n‫افتتحــت اجللســة يف هــذا اليــوم األربعــاء املوافق‪1434/10/7‬ه ـ الســاعة‬\n\n\n                                                                                             ‫‪290‬‬\n\f      ‫‪12 : 30‬بنــاء علــى ورود املعاملــة مــن محكمــة االســتئناف بعســير‬\n      ‫بخطــاب رئيســها رقــم ‪ 341945011‬وتاريــخ ‪1434/9/16‬ه ـ مصدق ـ ًا‬\n      ‫علــى احلكــم بالقــرار رقم‪34303182‬وتاريــخ ‪1434/8/23‬ه ـ الصــادر‬\n      ‫مــن الدائــرة احلقوقيــة الثانيــة عليــه فقــد جــرى التهميــش مبوجبــه وصلــى‬\n                          ‫اهلل وســلم علــى نبينــا محمــد حــرر يف‪1434/10/7‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتدقيــق‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بجــازان رقــم ‪341659475‬‬\n      ‫وتاريــخ ‪1434/7/26‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضي‬\n      ‫باحملكمــة الشــيخ‪ .........../‬رقــم ‪ 34198026‬وتاريــخ ‪1434/4/27‬ه ـ‬\n      ‫اخلــاص بدعــوى املدعــي وكالــه ‪ ( ...........‬ســعودي اجلنســية ) ضــد ‪/‬‬\n      ‫‪ (...........‬مينــي اجلنســية ) يف قضيــة ( حــادث مــروري ) علــى الصفــة‬\n      ‫املوضحــة يف الصــك املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n      ‫فيــه وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة‬\n      ‫علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                                               ‫وســلم ‪.‬‬\n\n\n\n\n‫‪291‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":285,"source_page_end":291,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fbf4c709f594aaf78412de6d5bc017437221f74ecd75107e255fec8a85a45fa0","normalized_text_hash":"525fb153bc8b6bd636a005b06b4c28d665e1399e14a9d81c0cca39725a9f9cec","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p285-34198026"},{"id":"e7c59e44-08d7-5a9b-b26e-b58dad082619","document_type":"judgment","category":"judicial","subcategory":"general","title":"دية -حادث مروري -وفاة مورث املدعن -مطالبة بدية قتل خطأ -مصادقة املدعى عليه على الدعوى -حكم بدية قتل خطأ حسب نسبة اخلطأ املقررة -إفهام املدعى عليه بكفارة قتل اخلطأ -إفهام املدعى عليه بالرجوع على العاقلة .","document_number":"33446055","case_number":"33488421","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بنجران","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/3","year":"1434","subject":"دية -حادث مروري -وفاة مورث املدعن -مطالبة بدية قتل خطأ -مصادقة املدعى عليه على الدعوى -حكم بدية قتل خطأ حسب نسبة اخلطأ املقررة -إفهام املدعى عليه بكفارة قتل اخلطأ -إفهام املدعى عليه بالرجوع على العاقلة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/11/3 :‬هـ‬\n                  ‫ُ‬                 ‫َر ْق ُم َّ‬\n                      ‫الص ِّك‪33446055 :‬‬\n                     ‫َر ْق ُم الدعوى‪33488421 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34195‬تاريخه‪1434/1/3 :‬هـ‬\n\n\n‫ديــة ‪ -‬حــادث مــروري ‪ -‬وفــاة مــورث املدعــن ‪ -‬مطالبــة بديــة قتــل خطــأ‬\n‫‪ -‬مصادقــة املدعــى عليــه علــى الدعــوى ‪ -‬حكــم بديــة قتــل خطــأ حســب‬\n‫نســبة اخلطــأ املقــررة ‪ -‬إفهــام املدعــى عليــه بكفــارة قتــل اخلطــأ ‪ -‬إفهــام‬\n                                      ‫املدعــى عليــه بالرجــوع علــى العاقلــة ‪.‬‬\n\n\n\n‫قولــه تعالــى « ومــا كان ملؤمــن أن يقتــل مؤمنــا إال خطــأ ومــن قتــل‬\n‫مؤمنــا خطــأ فتحريــر رقبــة مؤمنــة وديــة مســلمة إلــى أهلــه إال أن‬\n‫يصدقــوا فــإن كان مــن قــوم عــدو لكــم وهــو مؤمــن فتحريــر رقبــة‬\n‫مؤمنــة وإن كان مــن قــوم بينكــم وبينهــم ميثــاق فديــة مســلمة إلــى‬\n‫أهلــه وحتريــر رقبــة مؤمنــة فمــن لــم يجــد فصيــام شــهرين متتابعــن‬\n                                    ‫توبــة مــن اهلل وكان اهلل عليمــا حكيمــا »‪.‬‬\n\n\n\n‫ادعــى املدعــي وكالــة بــأن املدعــى عليــه تســبب يف وفــاة مــورث موكليه‬\n‫يف حــادث ســير حيــث قــام بدهســه خطــأ وقــد أديــن بنســبة اخلطــأ يف‬\n‫احلــادث بنســبة ‪ %50‬وطلــب املدعــي وكالــة إلــزام املدعــى عليــه بتســليم‬\n‫ديــة قتــل اخلطــأ حســب نســبة اخلطــأ املقــررة عليــه‪ ،‬صــادق املدعــى‬\n‫عليــه علــى الدعــوى‪ ،‬مت االطــاع علــى تقريــر احلــادث وأوراق املعاملــة‪،‬‬\n\n\n                                                                                      ‫‪292‬‬\n\f      ‫لألســباب املرصــودة يف نــص احلكــم ولقولــه تعالــى « ومــا كان ملؤمــن‬\n      ‫أن يقتــل مؤمنــا إال خطــأ ومــن قتــل مؤمنــا خطــأ فتحريــر رقبــة مؤمنــة‬\n      ‫وديــة مســلمة إلــى أهلــه إال أن يصدقــوا فــإن كان مــن قــوم عــدو لكــم‬\n      ‫وهــو مؤمــن فتحريــر رقبــة مؤمنــة وإن كان مــن قــوم بينكــم وبينهــم‬\n      ‫ميثــاق فديــة مســلمة إلــى أهلــه وحتريــر رقبــة مؤمنــة فمــن لــم يجــد‬\n      ‫فصيــام شــهرين متتابعــن توبــة مــن اهلل وكان اهلل عليمــا حكيمــا »‬\n      ‫صــدر احلكــم علــى املدعــى عليــه بتســليم الورثــة ديــة قتــل اخلطــأ حســب‬\n      ‫نســبة اخلطــأ املقــررة مائــة وخمســن ألــف ريــال وإفهــام املدعــى عليــه‬\n      ‫بكفــارة قتــل اخلطــأ ولــه الرجــوع علــى عاقلتــه‪ ،‬قــرر الطرفــان القناعــة‬\n      ‫باحلكــم‪،‬مت رفــع احلكــم للمحكمــة االســتئناف لوجــود قصــار‪ ،‬صــدر‬\n      ‫قــرار محكمــة االســتئناف باملصادقــة علــى احلكــم‪ ،‬حضــر املدعــي‬\n      ‫وكالــة وقــرر اســتالمه للمبلــغ احملكــوم بــه حيــث وكالتــه تخولــه‬\n                                                                           ‫االســتالم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ............‬القاضــي يف احملكمــة العامــة‬\n      ‫بنجــران وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بنجــران برقــم ‪ 33488421‬وتاريــخ ‪1433/07/26‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 331407142‬وتاريــخ ‪1433/07/26‬ه ـ فقــد حضــر‬\n      ‫املدعــي وكالــة‪ ............‬ســوداني اجلنســية مبوجــب رخصــة اإلقامــة رقــم‬\n      ‫‪ ............‬الوكيــل الشــرعي عــن ورثــة‪ ............‬وهــم كل مــن ‪ ......‬و‪......‬‬\n      ‫‪ -‬بصفتهــا وليــة علــى القصــر مــن ورثــة املتوفــى وهــم كل مــن‪............‬‬\n      ‫(‪13‬ســنة) و ‪ 7( ............‬ســنوات) مبوجــب اإلعــام الشــرعي رقــم‬\n\n‫‪293‬‬\n\f‫(‪2012/229‬م) ( وهــو غيــر مصــدق مــن اجلهــات املختصــة) ويتضمــن‬\n‫إثبــات وفــاة بتاريــخ ‪2012/03/12‬م وانحصــار إرثــه يف كل مــن والدتــه‬\n‫الســيد ويف زوجتــه ويف أوالده القاصريــن (‪13‬ســنة) و (‪7‬ســنوات)‬\n‫ويتضمــن أيضــا إقامــة علــى القاصريــن‪ ،‬مبوجــب الوكالــة الصــادرة‬\n‫مــن موثــق العقــود بجمهوريــة الســودان (وهــو غيــر مصــدق مــن اجلهــات‬\n‫املختصــة) ويخــول الوكيــل متابعــة ومطالبــة كافــة اإلجــراءات فيمــا‬\n‫يخــص حــادث الســير الــذي حصــل علــى مورثهــم يف كل مــا يتطلــب‬\n‫حضورهــم ولــه حــق توقيــع املســتندات واســتالم املبالــغ ســواء كانــت‬\n‫نقديــة أو بواســطة شــيك وحضــر حلضــوره ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم فجــرى إفهــام وكيــل الورثــة بــأن عليــه مصادقــة‬\n‫أوراقــه لــدى اجلهــات املختصــة قبــل عرضهــا ففهــم ذلــك ويف جلســة‬\n‫أخــرى حضــر املدعــي وكالــة وحضــر حلضــوره املدعــى عليــه وبســؤال‬\n‫املدعــي وكالــة عمــا رفعــت اجللســة املاضيــة ألجلــه أبــرز الوكالــة‬\n‫وقــد قــام بتصديقهــا مــن قــل اجلهــات املختصــة ومنهــا وزارة العــدل‬\n‫بعــدد ‪ 15044‬وتاريــخ ‪1433/09/20‬ه ـ مــن محافظــة جــدة كمــا أبــرز‬\n‫اإلعــان الشــرعي بالورثــة وقــد قــام بتصديقــه مــن قبــل اجلهــات املختصــة‬\n‫ومنهــا وزارة العــدل بتاريــخ ‪1433/10/15‬ه ـ وادعــى قائــا إنــه بتاريــخ‬\n‫‪1433/04/19‬ه ـ قــام هــذا احلاضــر معــي بدهــس مــورث موكلــي عــن‬\n‫طريــق اخلطــأ وذلــك أثنــاء عبــوره طريــق امللــك عبدالعزيــز غــرب إشــارة‬\n‫الصناعيــة وقــد كان املدعــى عليــه متجهــا ناحيــة البلــد يقــود ســيارته‬\n‫مــن نــوع كابريــس إنتــاج ‪1996‬م رقــم اللوحــة (‪ )....‬فضيــة اللــون وقد نتج‬\n‫عــن ذلــك وفاتــه وقــد أديــن مــن قبــل املــرور مبســؤوليته عــن احلادث بنســبة‬\n‫‪ %50‬لــذا أطلــب إلزامــه بدفــع الديــة املقدرة شــرعا بناء على نســبة اإلدانة‬\n\n\n                                                                                      ‫‪294‬‬\n\f      ‫املقــدرة مــن قبــل املــرور هكــذا ادعــى وبعــرض دعــوى املدعــي وكالــة‬\n      ‫علــى املدعــى عليــه أجــاب قائــا صحيــح مــا ذكــره املدعــي وكالــة‬\n      ‫جملــة وتفصيــا فقــد قمــت بدهــس املدعــو ســوداني اجلنســية وذلــك أثنــاء‬\n      ‫عبــوره طريــق امللــك عبدالعزيــز فقــد كنــت قادمــا مــن احلصينيــة قاصدا‬\n      ‫جنــران وبعــد جتــاوزي لإلشــارة فوجئــت بعبــور املتوفــى للطريــق فقمــت‬\n      ‫بدهســه عــن طريــق اخلطــأ وتــويف بعدهــا مباشــرة فقــد كنــت مســرعا‬\n      ‫قليــا وقــد أدنــت مبســؤوليتي عــن احلــادث بنســبة ‪ %50‬مــن قبــل املــرور‬\n      ‫وأنــا مقتنــع متامــا بهــذه النســبة هكــذا أجــاب فجــرى االطــاع علــى‬\n      ‫أوراق املعاملــة فوجــدت فيهــا رســما تخطيطيــا للحــادث علــى اللفــة رقــم‬\n      ‫(‪ )7‬وهــو كمــا جــاء يف الدعــوى واإلجابــة كمــا جــرى االطــاع علــى‬\n      ‫محضــر إقــرار القناعــة واملــدون علــى الصفحــة رقــم (‪ )6‬مــن محاضــر‬\n      ‫إجــراءات االســتدالل املرفــق باملعاملــة علــى اللفــة رقــم (‪ )1‬ويتضمــن‬\n      ‫إقــرار املدعــى عليــه بالنســبة املقــررة لــه مــن قبــل املــرور وهــي (‪)%50‬‬\n      ‫كمــا جــرى االطــاع علــى محضــر االنتقــال واملعاينــة مــن ذات الدفتــر‬\n      ‫علــى الصفحــة رقــم (‪ )2‬وهــو كمــا جــاء يف الدعــوى واإلجابــة كمــا‬\n      ‫جــرى االطــاع علــى محضــر تأييــد النســبة املعــد مــن قبــل مــرور مدينــة‬\n      ‫جنــران علــى اللفــة رقــم (‪ )23‬ويتضمــن إدانــة املدعــى عليــه باخلطأ بنســبة‬\n      ‫(‪ )%50‬لألســباب التاليــة ‪ )1( :‬عــدم مراعــاة األنظمــة بتجــاوز الســرعة‬\n      ‫احملــددة ممــا يــدل علــى ذلــك جســامة احلــادث (‪ )2‬قلــة االحتــراز وعــدم‬\n      ‫أخــد احليطــة واحلــذر أثنــاء الســير (‪ )3‬إهمالــه مبباشــرة الصــدم مبقدمــة‬\n      ‫الســيارة بشــكل مباشــر ‪0‬كمــا أديــن املتوفــى بنســبة خطــأ قدرهــا‬\n      ‫(‪ )%50‬وذلــك لألســباب التاليــة‪ )1(:‬قلــة االحتــراز بقطعــه للطريــق دون‬\n      ‫التأكــد مــن خلــوه مــن الســيارات (‪ )2‬عــدم مراعاتــه لألنظمــة املروريــة‬\n\n\n‫‪295‬‬\n\f‫الســيما وأن املوقــع غيــر مخصــص لعبــور املشــاة فجــرى ســؤال كل مــن‬\n‫املدعــي وكالــة واملدعــى عليــه عــن أيــة إضافــة يــودان إضافتهــا فأجــاب‬\n‫كل واحــد منهمــا مبفــرده ال إضافــة لــدي هكــذا أجابــا فبنــاء علــى مــا‬\n‫تقــدم مــن الدعــوى واإلجابــة ومصادقــة املدعــى عليــه ملــا جــاء فيهــا جملــة‬\n                   ‫وتفصيــا وملــا جــاء يف إقــرار نســبة القناعــة املشــار إليــه‬\n‫و ملــا جــاء يف محضــر إعــداد نســبة اخلطــأ املشــار إليــه وملا جــاء يف محضر‬\n‫املعاينــة املعــد مــن قبــل املــرور ولقــول اهلل عــز وجــل ((ومــا كان ملؤمــن‬\n‫أن يقتــل مؤمنــا إال خطــأ ومــن قتــل مؤمنــا خطــأ فتحريــر رقبــة مؤمنــة‬\n‫وديــة مســلمة إلــى أهلــه إال أن يصدقــوا فــإن كان مــن قــوم عــدو لكــم‬\n‫وهــو مؤمــن فتحريــر رقبــة مؤمنــة وإن كان مــن قــوم بينكــم وبينهــم‬\n‫ميثــاق فديــة مســلمة إلــى أهلــه وحتريــر رقبــة مؤمنــة فمــن لــم يجــد‬\n‫فصيــام شــهرين متتابعــن توبــة مــن اهلل وكان اهلل عليمــا حكيمــا))‬\n‫فقــد حكمــت علــى املدعــى عليــه بدفــع مبلــغ قــدره مائــة وخمســون ألــف‬\n‫ريــال تســلم لورثــة املتوفــى ويكــون نصيــب والدتــه مبلغــا قــدره خمســة‬\n‫وعشــرون ألــف ريــال ويكــون نصيــب الزوجــة مبلغــا قــدره ثمانيــة عشــر‬\n‫ألفــا وســبعمائة وخمســون ريــاال ويكــون نصيــب كل واحــد مــن االبنــن‬\n‫و مبلغــا قــدره ثالثــة وخمســون ألفــا ومائــة وخمســة وعشــرون ريــاال كمــا‬\n‫جــرى إفهــام املدعــى عليــه بــأن عليــه كفــارة قتــل اخلطــأ عتــق رقبــة فــإن‬\n‫لــم يجــد فصيــام شــهرين متتابعــن كمــا جــرى إفهامــه بــأن لــه الرجــوع‬\n‫علــى عاقلتــه إن صدقتــه وبإعــان احلكــم قــرر كل مــن املدعــي وكالــة‬\n‫واملدعــى عليــه القناعــة وأمــرت بإرســال الصــك ومــا مت ضبطــه حملكمــة‬\n‫االســتئناف لتدقيــق احلكــم لوجــود القصــر وبــاهلل التوفيــق وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1433/10/28‬هــ‪0‬‬\n\n\n                                                                                       ‫‪296‬‬\n\f      ‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن ‪1434/01/26‬هـ عــادت املعاملة‬\n      ‫مــن محكمــة االســتئناف مبوجــب اخلطــاب رقــم ‪ 332241658‬وتاريــخ‬\n      ‫‪1434/01/13‬ه ـ ومرفــق بــه قــرار التصديــق رقــم ‪ 34195‬وتاريــخ‬\n      ‫‪1434/01/03‬ه ـ ونــص احلاجــة منــه « وبدراســة الصــك وصــورة ضبطــه‬\n      ‫وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل‬\n      ‫وســلم علــى نبينــا محمــد وآلــه وصحبــه وســلم قاضــي اســتئناف ‪...........‬‬\n      ‫ختمــه وتوقيعــه قاضــي اســتئناف ‪ ...........‬ختمــه وتوقيعــه رئيــس الدائــرة‬\n      ‫‪ ...........‬ختمــه وتوقيعــه» واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمد‬\n                                  ‫وآلــه وصحبــه وســلم حــرر يف ‪1434/01/26‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬القاضــي يف احملكمــة العامــة‬\n      ‫بنجــران والقائــم بعمــل املكتــب القضائــي الرابــع ففــي يــوم األربعــاء‬\n      ‫‪1434/08/03‬ه ـ حضــر املدعــي وكالــة ولكــون وكالتــه تخولــه‬\n      ‫اســتالم املبالــغ ســواء كانــت نقديــة أو بواســطة شــيك فقــد جــرى‬\n      ‫تســليمه الشــيك رقــم ‪ 024725‬وتاريــخ ‪2013/05/29‬م واملســحوب‬\n      ‫علــى مصــرف الراجحــي مببلــغ قــدره مائــة وخمســون ألــف ريــال وقــرر‬\n      ‫املدعــي وكالــة قائــا لــم يعــد موكلـ ّـي يطالبــون املدعــى عليــه بــأي‬\n      ‫مبلــغ يخــص هــذه الدعــوى هكــذا قــرر وبذلــك تكــون القضيــة منتهيــة‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر‬\n                                                              ‫يف ‪1434/08/03‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n      ‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بنجــران برقــم‬\n      ‫‪ 331407142‬وتاريــخ ‪1433/11/29‬ه ـ املرفــق بهــا الصــك الشــرعي‬\n\n\n‫‪297‬‬\n\f‫الصــادر مــن فضيلــة الشــيخ ‪ /‬برقــم ‪ 33446055‬وتاريــخ ‪1433/11/3‬هـ‬\n‫اخلــاص بدعــوى ‪ ( .........../‬ســوداني اجلنســية ) ضــد ‪ ( .........../‬ســعودي‬\n‫اجلنســية ) يف قضيــة ( حــادث مــروري ) علــى الصفــة املوضحــة يف الصك‬\n‫املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة الصــك‬\n‫وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم ‪ .‬واهلل‬\n            ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪298‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":292,"source_page_end":298,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9c6d2ac08ff8ca19d15f2aff54c64ea2b9a73f1f7b5a0f4bd98b7ea8822d3f1d","normalized_text_hash":"57f0798cb1bd9828ad70c129759446c4c7d0bc14310026bea63912d32ab7cffe","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p292-33446055"},{"id":"3f236360-cb4e-5586-a81b-d0ae9cfb5528","document_type":"judgment","category":"judicial","subcategory":"general","title":"دية -حادث مروري -وفاة مورث املدعن -اإلدانة الكاملة للمدعى عليه -مصادقة املدعى عليه على الدعوى -حكم بتسليم دية قتل خطأ -سداد الدية على ثاث سنوات -إفهام احملكوم عليه بتسليم دية قتل اخلطأ بأن له الرجوع على عاقلته .","document_number":"333423491","case_number":"33516714","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/11","year":"1434","subject":"دية -حادث مروري -وفاة مورث املدعن -اإلدانة الكاملة للمدعى عليه -مصادقة املدعى عليه على الدعوى -حكم بتسليم دية قتل خطأ -سداد الدية على ثاث سنوات -إفهام احملكوم عليه بتسليم دية قتل اخلطأ بأن له الرجوع على عاقلته .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/10/11 :‬هـ‬\n                        ‫ُ‬                 ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪333423491 :‬‬\n                           ‫َر ْق ُم الدعوى‪33516714 :‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34332712‬تاريخه‪1434/10/18 :‬ه‬\n\n\n        ‫ديــة ‪ -‬حــادث مــروري ‪ -‬وفــاة مــورث املدعــن ‪ -‬اإلدانــة الكاملــة للمدعــى‬\n        ‫عليــه ‪ -‬مصادقــة املدعــى عليــه علــى الدعــوى ‪ -‬حكــم بتســليم ديــة قتــل‬\n        ‫خطــأ ‪ -‬ســداد الديــة علــى ثــاث ســنوات ‪ -‬إفهــام احملكــوم عليــه بتســليم‬\n                                  ‫ديــة قتــل اخلطــأ بــأن لــه الرجــوع علــى عاقلتــه ‪.‬‬\n\n\n\n        ‫‪ -1‬قــال يف كشــاف القنــاع « ومــا حتملــه العاقلــة يجــب مؤجــا يف‬\n        ‫ثــاث ســنني لقــول عمــر وعلــى يف ديــة اخلطــأ ولــم يعــرف لهمــا مخالــف‬\n        ‫فــكان كاإلجمــاع يف آخــر كل ســنة ثلثــه إن كان الواجــب ديــة كامــل‬\n              ‫ديــة النفــس ثــم قــال وابتــداء احلــول يف القتــل مــن حــن املــوت »‬\n        ‫‪ -2‬جــاء يف االختيــارات البــن تيميــة (ص ‪( : )424‬وتؤخــذ الديــة مــن‬\n        ‫اجلانــي خطــأ عنــد تعــذر العاقلــة يف أصــح قولــي العلمــاء وال تؤجــل‬\n        ‫علــى العاقلــة إذا رأى اإلمــام املصلحــة فيــه ونــص علــى ذلــك اإلمــام‬\n                                                                             ‫أحمــد) ‪.‬‬\n        ‫وقــال يف موضــع آخــر (ص ‪( : )111‬وال تأجيــل يف الديــة وأنــه نــص‬\n        ‫أحمــد فيهــا ألن النبــي صلــى اهلل عليــه وســلم لــم يؤجلهــا وإن رأى‬\n        ‫اإلمــام تأجيلهــا فعــل ألن عمــر أجلهــا فأيهمــا رأى اإلمــام فعــل وإال‬\n                                              ‫فإيجــاب أحــد األمريــن ال يســوغ) ‪.‬‬\n        ‫‪ -3‬قــال اإلمــام الترمــذي ‪( :‬قــد أجمــع أهــل العلــم علــى أن الديــة تؤخــذ‬\n                                                                   ‫يف ثــاث ســنني) ‪.‬‬\n‫‪299‬‬\n\f          ‫‪ -4‬قال ابن بطال ‪( :‬أجمعوا أن الدية تقطع يف ثالث سنني) ‪.‬‬\n‫‪ -5‬قــال ابــن قدامــة ‪( :‬وال أعلــم يف أنهــا جتــب مؤجلــة خالفـ ًا بــن أهــل‬\n‫العلــم وروى ذلــك عــن ‪ :‬عمــر وعلــي وابــن عبــاس وبــه قــال الشــعبي‬\n‫والنخعــي وقتــادة وأبــو هاشــم وعبــداهلل بــن عمــر ومالــك والشــافعي‬\n                                         ‫وإســحاق وأبــو ثــور وابــن املنــذر) ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي أصالــة ووكالــة بــأن املدعــى عليــة تســبب يف وفــاة مورثهم‬\n‫بســبب حــادث مــروري حيــث أديــن املدعــى عليه بنســبة اخلطأ مائــة باملائة‬\n‫‪ %100‬وطالــب املدعــى أصالــة ووكالــة بتســليمه وموكليــه نصيبهــم‬\n‫مــن ديــة القتــل اخلطــأ‪ ،‬أجــاب املدعــى عليــه باملصادقــة‪ ،‬صــدر احلكــم‬\n‫علــى املدعــى عليــه بتســليم املدعــى وموكليــه نصيبهــم مــن ديــة قتــل‬\n‫اخلطــأ وأفهــم املدعــى عليــه بــأن لــه الرجــوع علــى عاقلتــة‪ ،‬قــرر املدعــى‬\n‫عليــه عــدم القناعة‪،‬صــدر قــرار محكمــة االســتئناف باملالحظــة علــى‬\n‫تأجيــل الديــة احملكــوم بهــا علــى ثــاث ســنني لألســباب املشــار إليهــا‬\n‫يف القــرار‪ ،‬صــدر احلكــم بتأجيــل الديــة احملكــوم بهــا علــى ثــاث‬\n‫ـداء مــن تاريــخ الوفــاة وتدفــع آخــر الســنة ثلــث احملكــوم لــه‬\n                                                                   ‫ســنني ابتـ ً‬\n‫واســتند ناظــر القضيــة إلــى مــا جــاء يف كشــاف القنــاع « ومــا حتملــه‬\n‫العاقلــة يجــب مؤجــا يف ثــاث ســنني لقــول عمــر وعلــى يف ديــة اخلطــأ‬\n‫ولــم يعــرف لهمــا مخالــف فــكان كاإلجمــاع يف آخــر كل ســنة ثلثــه‬\n‫إن كان الواجــب ديــة كامــل ديــة النفــس ثــم قــال وابتــداء احلــول يف‬\n‫القتــل مــن حــن املوت»‪،‬صــدر قــرار محكمــة االســتئناف باملصادقــة‬\n                                                                 ‫علــى احلكــم ‪.‬‬\n\n                                                                                     ‫‪300‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ...........‬القاضــي يف احملكمــة العامــة‬\n      ‫بعنيــزة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بعنيــزة برقــم ‪ 33516714‬وتاريــخ ‪ 1433/08/11‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 331499080‬وتاريــخ ‪ 1433/08/10‬ه ـ ففــي يــوم‬\n      ‫األربعــاء املوافــق‪ 1433/10/11‬ه ـ افتتحــت اجللســة الســاعة ‪08 : 30‬‬\n      ‫وحضــر فيهــا‪ ...........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪...........‬وادعــى علــى احلاضــر معــه ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪ ...........‬قائــا يف دعــواه إنــه بتاريــخ ‪1432/8/14‬ه ـ تــويف‬\n      ‫والــدي وانحصــر إرثــه يف زوجتيــه و وأوالده فقــط مبوجــب صــك حصــر‬\n      ‫الورثــة الصــادر مــن احملكمــة العامــة بالريــاض برقــم ‪ 32333123‬يف‬\n      ‫‪1432/11/25‬ه ـ وقــد كانــت وفاتــه بســبب حــادث مــروري وقــع يف‬\n      ‫‪1432/8/14‬ه ـ يف طريــق الروضــة يف عنيــزة بــن ســيارتني األولــى‬\n      ‫بقيــادة املتوفــى مــن نــوع جيــب صالــون صنــع ‪ 2009‬والثانيــة ســيارة مــن‬\n      ‫نــوع جيــب شــاص صنــع ‪ 2010‬بقيــادة املدعــى عليــه وأديــن املدعــى عليــه‬\n      ‫بنســبة اخلطــأ كاملــة ‪ %100‬يف احلــادث املذكــور ثــم توفيــت زوجــة‬\n      ‫املتوفــى وانحصــر إرثهــا يف والدهــا ووالدتهــا وابنهــا القاصــر وذلــك‬\n      ‫مبوجــب صــك حصــر الورثــة الصــادر مــن محكمــة الشــبيكية برقــم ‪6‬‬\n      ‫يف ‪1433/4/6‬هـ املجلد ‪ 2‬ص ‪ 23‬وأنا وكيل عن ورثة املتوفى األحياء‬\n      ‫وهــم كل مــن ‪ ...........‬ومبوجــب الوكالــة الصــادرة مــن كتابــة عــدل‬\n      ‫البدائــع برقــم ‪ 973‬يف ‪1433/3/12‬ه ـ وعــن كل مــن ‪ ...........‬مبوجــب‬\n      ‫الوكالــة الصــادرة مــن كتابــة البدائــع برقــم ‪ 977‬يف ‪1433/3/12‬ه ـ‬\n\n‫‪301‬‬\n\f‫وعــن‪ ...........‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل الــرس برقــم‬\n‫‪ 960605006517‬يف ‪1432/10/30‬ه ـ وعــن‪ ...........‬مبوجــب الوكالــة‬\n‫الصــادرة مــن كتابــة عــدل الثانيــة بجنــوب الريــاض برقــم ‪ 86595‬يف‬\n‫‪1432/10/28‬ه ـ اجللــد ‪ 5317‬وعــن‪ ...........‬مبوجــب الوكالــة الصــادرة‬\n‫مــن كتابــة عــدل البدائــع برقــم ‪ 3518‬يف ‪1432/10/12‬ه ـ و‪...........‬‬\n‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة باحلائــر برقــم‬\n‫‪ 32329542‬يف ‪1432/11/21‬هـ وعن كل من ‪ ...........‬مبوجب الوكالة‬\n‫الصــادرة مــن كتابــة عــدل الثانيــة بجنــوب الريــاض برقــم ‪ 86621‬يف‬\n‫‪1432/10/28‬ه ـ وعــن ‪ ...........‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n‫عــدل ينبــع برقــم ‪ 32289060‬يف ‪1432/10/30‬ه ـ وعــن‪ ...........‬مبوجــب‬\n‫الوكالــة الصــادرة مــن محكمــة القــوارة برقــم ‪ 752‬يف ‪1432/11/4‬ه ـ‬\n‫اجللــد ‪ 181‬وعــن‪ ...........‬بصفتــه وليــا جبريــا عــن الوارثــة املتوفــاة املولــود‬\n‫يف ‪1422/8/15‬ه ـ مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n‫الثانيــة بشــرق الريــاض برقــم ‪ 3343392‬يف ‪1433/4/12‬ه ـ وباألصالــة‬\n‫عــن نفســي ونيابــة عــن موكلــي أطلــب احلكــم علــى املدعــى عليــه‬\n‫بتســليمي أنــا وموكلــي نصيبنــا مــن ديــة قتــل املدعــى عليــه مورثنــا خطــأ‬\n‫هــذه دعــواي وبســؤال املدعــى عليــه عــن دعــوى املدعــي أصالــة ووكالــة‬\n‫أجــاب بقولــه كل مــا ذكــره املدعــي أصالــة ووكالــة يف دعــواه صحيــح‬\n‫جملــة وتفصيــا هكــذا أجــاب املدعــى عليــه وقــد اطلعــت علــى‬\n‫صكــوك حصــر الورثــة والــوكاالت التــي ذكرهــا املدعــي فوجدتهــا‬\n‫كمــا ذكــر فبنــاء علــى مــا تقــدم مــن دعــوى املدعــي أصالــة ووكالــة‬\n‫وملصادقــة املدعــى عليــه علــى مــا جــاء فيهــا فقــد حكمــت علــى املدعــى‬\n‫عليــه بــأن يدفــع للمدعــي وموكليــه نصيبهــم مــن ديــة قتلــه مورثهــم خطأ‬\n\n\n                                                                                          ‫‪302‬‬\n\f      ‫للزوجــة نصــف الثمــن وقــدره ثمانيــة عشــر ألفــا وســبعمائة وخمســون‬\n      ‫ريــاال ابــن الزوجــة املتوفــاة اثنــا عشــر ألفــا وخمســمائة ريــال وهــو الباقــي‬\n      ‫مــن نصــف الثمــن الــذي تســتحقه مــن الديــة بعــد خصــم سدســي والديهــا‬\n      ‫اللذيــن لــم يحضــرا أو يــوكال والباقــي مــن الديــة بعــد الثمــن وقــدره‬\n      ‫مائتــان واثنــان وســتون ألفــا وخمســمائة ريــال ألوالد املتوفــى للذكــر‬\n      ‫مثــل حــظ االنثيــن لــكل ابــن خمســة وعشــرون ألــف ريــال ولــكل بنــت‬\n      ‫اثنــا عشــرا ألفــا وخمســمائة ريــال وللمدعــى عليــه الرجــوع علــى عاقلتــة‬\n      ‫بالديــة حســب الوجــه الشــرعي وعليــه كفــارة قتــل اخلطــأ املذكــورة‬\n      ‫يف ســورة النســاء آيــة ‪ 92‬وبعــرض احلكــم علــى املدعــى عليــه قــرر عــدم‬\n      ‫القناعــة بــه وطلــب االســتئناف بالئحــة اعتراضيــة فأفهــم بأنــه ســوف‬\n      ‫يســلم صــورة مــن الصــك يف هــذا اليــوم بعــد التوقيــع علــى الضبــط لتقــدمي‬\n      ‫الالئحــة االعتراضيــة عليــه خــال ثالثــن يومــا مــن تاريــخ اليــوم فــإن لــم‬\n      ‫يقــدم الالئحــة خاللهــا ســقط حقــه يف االســتئناف واكتســب احلكــم‬\n      ‫القطعيــة وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى صحابتــه أجمعــن‪.‬‬\n                                                            ‫حــرر يف ‪1433/10/11‬ه‪.‬ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ...........‬القاضــي يف احملكمــة العامــة‬\n      ‫بعنيــزة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بعنيــزة برقــم ‪ 33516714‬وتاريــخ ‪ 1433/08/11‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 331499080‬وتاريــخ ‪ 1433/08/10‬ه ـ ففــي يــوم‬\n      ‫األحــد املوافــق‪ 1434/02/24‬ه ـ افتتحــت اجللســة الســاعة ‪ 45:11‬وقــد‬\n      ‫وردتنــا املعاملــة مــن محكمــة اإلســتئناف مبنطقــة القصيــم وبرفقهــا‬\n      ‫القــرار محكمــة اإلســتئناف مبنطقــة القصيــم رقــم ‪ 3423766‬يف‬\n      ‫‪1434/1/26‬ه ـ املتضمــن مــا نصــه بعــد املقدمــة وبدراســة القــرار‬\n\n\n‫‪303‬‬\n\f‫وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة لوحــظ أن‬\n‫فضيلتــه حكــم علــى املدعــى عليــه بدفــع ديــة قتــل اخلطأ عليــه وموكليه‬\n‫وديــة قتــل اخلطــأ مؤجلــة علــى العاقلــة يف ثــاث ســنني ولــم ينــوه عــن ذلــك‬\n‫فعلــى فضيلتــه التأمــل وإعــادة النظــر وإجــراء الــازم انتهــى وعليــه أجيــب‬\n‫أصحــاب الفضيلــة قضــاة االســتئناف حفظهــم اهلل تعالــى بــأن تأجيــل‬\n‫الديــة أمــر اجتهــادي جــاء يف االختيــارات البــن تيميــة ص (‪( )424‬وتؤخــذ‬\n‫الديــة مــن اجلانــي خطــأ عنــد تعــذر العاقلــة يف أصــح قولــي العلمــاء وال‬\n‫تؤجــل علــى العاقلــة إذا رأى اإلمــام املصلحــة فيــه ونــص علــى ذلــك اإلمــام‬\n‫أحمــد) انتهــى مــن االختيــارات وجــاء يف موضــع آخــر مــن االختيــارات‬\n‫يف ص (‪ )111‬مــا نصــه (وال تأجيــل يف الديــة وأنــه نــص أحمــد فيهــا ألن‬\n‫النبــي ‪ -‬صلــى اهلل عليــه وســلم ‪ -‬لــم يؤجلهــا وإن رأى اإلمــام تأجيلهــا‬\n‫فعــل ألن عمــر أجلهــا فأيهمــا رأى اإلمــام فعــل وإال فإيجــاب أحــد األمرين‬\n‫ال يســوغ) انتهــى مــن االختيــارات وال أرى مســوغا لتأجيــل الديــة هنــا‬\n‫وقــد صــدرت أحــكام قضائيــة كثيــرة باإللــزام بدفــع الديــة دون تأجيــل‬\n‫ومنهــا علــى ســبيل املثــال احلكــم الصــادر منــي بالقــرار رقــم ‪33282081‬‬\n‫يف ‪1433/6/4‬ه ـ املصــدق مــن محكمــة االســتئناف بالقصيــم بقرارهــا‬\n‫رقــم ‪ 33382673‬يف ‪1433/8/18‬ه ـ هــذا مــا أجيــب بــه ولــم يظهــر‬\n‫خــاف مــا حكمــت بــه وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                      ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/02/24‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ...........‬القاضــي يف احملكمــة العامــة‬\n‫بعنيــزة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بعنيــزة برقــم ‪ 33516714‬وتاريــخ ‪1433/08/11‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331499080‬وتاريــخ ‪1433/08/10‬ه ـ ففــي يــوم‬\n\n\n                                                                                       ‫‪304‬‬\n\f      ‫األحــد املوافــق ‪1434/09/06‬ه ـ افتتحــت اجللســة وقــد عــادت املعاملــة‬\n      ‫مــن محكمــة االســتئناف بالقصيــم وبرفقهــا قــرار محكمة االســتئناف‬\n      ‫بالقصيــم رقــم ‪ 34218904‬يف ‪1434/5/21‬ه ـ ونصــه بعــد املقدمــة وقــد‬\n      ‫ســبق منــا دراســة القــرار وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى‬\n      ‫مــا أجــاب بــه فضيلتــه وأحلــق بالقــرار وضبطــه بنــاء علــى قرارنــا رقــم‬\n      ‫‪ 3423766‬وتاريــخ ‪1434/1/26‬ه ـ لوحــظ أن مــا أجــاب بــه فضيلتــه‬\n      ‫علــى قرارنــا املشــار إليــه بعاليــه غيــر مقنــع وال مــاق ملــا طلــب منــه ومــا‬\n      ‫أشــار إليــه مــن أن التأجيــل أمــر اجتهــادي أنهــا ال تؤجــل علــى العاقلــة‬\n      ‫إذا رأى اإلمــام املصلحــة غيــر مســلم بــه فقــد قــال اإلمــام الترمــذي (قــد‬\n      ‫أجمــع أهــل العلــم علــى أن الديــة تؤخــذ يف ثالثــة ســنني) وقــال ابــن بطــال‬\n      ‫(أجمعــوا أن الديــة تقطــع يف ثــاث ســنني) وقــال ابــن قدامــة املقدســي‬\n      ‫(وال أعلــم يف أنهــا جتــب مؤجلــة خالفــا بــن أهــل العلــم وروي ذلــك عــن‬\n      ‫عمــر وعلــي وابــن عبــاس وبــه قــال الشــعبي والنخعــي وقتــادة وأبــو هاشــم‬\n      ‫وعبــداهلل بــن عمــر ومالــك والشــافعي وإســحاق وأبــو ثــور وابــن املنــذر)‬\n      ‫ومبــا أن لــه الرجــوع علــى العاقلــة فتأجيلهــا علــى ثــاث ســنني أرفــق بــه‬\n      ‫وبهــم فعلــى فضيلتــه التأمــل وإعــادة النظــر وإجــراء الــازم انتهــى قــرار‬\n      ‫االســتئناف وقــد حضــر املدعــي أصالــة ووكالــة ‪ ........‬كمــا حضــر‬\n      ‫املدعــى عليــه وقــد جــرى تأمــل املعاملــة ونظــرا ملــا جــاء يف قــرار أصحــاب‬\n      ‫الفضيلــة ولقناعتــي مبــا جــاء فيــه ونظــرا إلــى أن ابتــداء احلــول يف القتــل‬\n      ‫مــن حــن املــوت قــال يف كشــاف القنــاع (‪( )64/6‬ومــا حتملــه العاقلــة‬\n      ‫يجــب مؤجــا يف ثــاث ســنني لقــول عمــر وعلــي يف ديــة اخلطــأ ولــم‬\n      ‫يعــرف لهمــا مخالــف فــكان كاإلجمــاع يف آخــر كل ســنة ثلثــه إن‬\n      ‫كان الواجــب ديــة كاملــة كديــة النفــس ثــم قــال و ابتــداء احلــول يف‬\n\n\n‫‪305‬‬\n\f‫القتــل مــن حــن املــوت) انتهــى ‪ .‬ولذلــك فقــد حكمــت بتأجيــل احملكــوم‬\n‫بــه مــن الديــة علــى املدعــى عليــه ليكــون علــى ثــاث ســنني ابتــداء مــن‬\n‫تاريــخ الوفــاة ‪1432/8/14‬ه ـ يدفــع يف آخــر كل ســنة ثلــث احملكــوم‬\n‫بــه مــن الديــة علــى أن يحــل آخــر قســط يف ‪1435/8/14‬ه ـ وبعــرض‬\n‫احلكــم بالتأجيــل علــى الطرفــن قــررا القناعــة بــه وســوف يرفــع احلكــم‬\n‫لالســتئناف لوجــود قاصــر يف الورثــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n    ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/09/06‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ...........‬املــازم القضائــي القائــم بعمــل‬\n‫فضيلــة الشــيخ‪ ...........‬القاضــي يف احملكمــة العامــة بعنيــزة أثنــاء‬\n‫إجازتــه وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بعنيــزة برقــم ‪ 33516714‬وتاريــخ ‪ 1433/08/11‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331499080‬وتاريــخ ‪ 1433/08/10‬ه ـ ففــي‬\n‫يــوم اإلثنــن املوافــق‪ 1434/11/03‬ه ـ افتتحــت اجللســة وقــد عــادت‬\n‫املعاملــة مــن محكمــة االســتئناف بالقصيــم برقــم ‪342196887‬‬\n‫يف‪1434/10/26‬ه ـ وبرفقهــا قــرار محكمــة االســتئناف بالقصيــم‬\n‫رقــم ‪ 34332712‬يف ‪1434/10/18‬ه ـ املتضمــن مــا نصــه بعــد املقدمــة‬\n‫باإلطــاع علــى مــا أجــاب بــه فضيلتــه وأحلقــه بالقــرار وضبطــه بنــاء علــى‬\n‫قرارنــا رقــم ‪ 34250888‬وتاريــخ ‪1434/6/25‬ه ـ قررنــا املصادقــة علــى‬\n‫احلكــم بعــد االجــراء واإليضــاح االخيريــن وبــاهلل التوفيــق وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/11/3‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى‬\n‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف ب ـمـنـط ـق ــة الـق ـص ـيـ ــم‬\n‫علــى املعاملــة الــواردة مــن فضيلــة رئي ـ ــس احملكمــة العامــة مبحافظــة‬\n\n\n                                                                                       ‫‪306‬‬\n\f      ‫عنيــزة برقــم (‪ )341438890‬وتاريــخ ‪1434/9/8‬هــ؛ املقيــدة لدينــا‬\n      ‫برقــم (‪ )342196887‬وتاريــخ ‪1434/9/16‬هــ؛ املرفــق بهــا القــرار‬\n      ‫رقــم (‪ )3/33423491‬وتاريــخ ‪1433/10/11‬هــ؛ الصــادر مــن فضيلــة‬\n      ‫الشــيخ‪ .........../‬القاضــي باحملكمــة؛ اخلــاص بدعــوى‪ ...........‬باألصالــة‬\n      ‫والوكالــة عــن ورثــة والــده ضــد‪،........... /‬مبطالبتــه بدفــع ديــة مورثيهــم‬\n      ‫نتيجــة حــادث مــروري ‪،‬وقــد تضمــن القــرار حكــم فضيلتــه بــأن يدفــع‬\n      ‫املدعــى عليــه للمدعــي ديــة قتــل اخلطــأ؛ علــى النحــو املفصــل فيــه‪ ،‬وقــد‬\n      ‫ســبق منــا دراســة القــرار وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى‬\n      ‫ـاء علــى قرارنــا رقــم‬\n                            ‫مــا أجــاب بــه فضيلتــه وأحلقــه ب ــ(القــرار وضبطــه) بنـ ً‬\n      ‫(‪ )34250888‬وتاريــخ ‪1434/6/25‬ه ـ ؛ قررنــا املصادقــة علــى احلكــم‬\n      ‫بعــد اإلجــراء واإليضــاح األخيريــن‪ .‬واهلل املوفــق‪ ،‬وصلــى اهلل وســلم علــى‬\n                                                                          ‫نبينــا محمــد ‪.‬‬\n\n\n\n\n‫‪307‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":299,"source_page_end":307,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d25ca817390c4c7b9f8c621479333d3222bc39ede7128e34bae018375ea43de0","normalized_text_hash":"228ee67f060d55f1348bd77ff0c0228169275385d2e08f6182806441ad127de4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p299-333423491"},{"id":"73486644-f212-5ce9-899f-0d1033af80cc","document_type":"judgment","category":"judicial","subcategory":"general","title":"دية -حادث مروري -وفاة مورث املدعن -اإلدانة الكاملة للمدعى عليه -مصادقة املدعى عليه على الدعوى -حكم بتسليم دية قتل اخلطأ -إفهام املدعى عليه بأن له الرجوع على عاقلته -إفهام املدعى عليه بأن عليه كفارة قتل اخلطأ.","document_number":"3452403","case_number":"33523501","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالباحة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/1","year":"1434","subject":"دية -حادث مروري -وفاة مورث املدعن -اإلدانة الكاملة للمدعى عليه -مصادقة املدعى عليه على الدعوى -حكم بتسليم دية قتل اخلطأ -إفهام املدعى عليه بأن له الرجوع على عاقلته -إفهام املدعى عليه بأن عليه كفارة قتل اخلطأ.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/3/1 :‬هـ َر ْق ُم‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                            ‫الص ِّك‪3452403 :‬‬\n                             ‫الدعوى‪33523501 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34167954‬تاريخه‪1434/3/22 :‬هـ‬\n\n\n ‫ديــة ‪ -‬حــادث مــروري ‪ -‬وفــاة مــورث املدعــن ‪ -‬اإلدانــة الكاملــة للمدعــى‬\n ‫عليــه ‪ -‬مصادقــة املدعــى عليــه علــى الدعــوى ‪ -‬حكــم بتســليم ديــة قتــل‬\n ‫اخلطــأ ‪ -‬إفهــام املدعــى عليــه بــأن لــه الرجــوع علــى عاقلتــه ‪ -‬إفهــام‬\n                             ‫املدعــى عليــه بــأن عليــه كفــارة قتــل اخلطــأ‪.‬‬\n\n\n\n\n ‫تعميــم معالــي رئيــس املجلــس األعلــى للقضــاء رقــم ‪/192‬ت يف‬\n ‫‪ 1432/10/9‬ه ـ املبنــى علــى قــرار مجلــس الــوزراء رقــم ‪ 43108‬يف‬\n ‫‪1432/10/2‬ه ـ املبنــى علــى قــرار الهيئــة العامــة للمحكمــة العليــا‬\n ‫املتضمــن اعــادة تقييــم الديــات بحيــث تكــون ديــة قتــل اخلطــأ مبلغــا‬\n                                    ‫قــدره ثالثمائــة ألــف ريــال للرجــل ‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي وكالــة بــأن املدعــى عليــه تســبب يف وفــاة مــورث موكليه‬\n ‫يف حــادث ســير وأديــن بنســبة اخلطــأ مائــة باملائــة وطالــب بإلــزام املدعــى‬\n ‫عليــه بتســليم موكليــه ديــة قتــل اخلطــأ مبلغــا قــدرة ثالثمائــة ألــف ريــال‪،‬‬\n ‫صــادق املدعــى عليــه علــى الدعــوى إال أنــه غيــر قــادر علــى تســليم الديــة‬\n ‫كاملــة‪ ،‬مت االطــاع علــى تقريــر حــادث املــرور وأســباب اإلدانــة والتــي‬\n ‫أكــدت إدانــة املدعــى عليــه إدانــة كاملــة وقــد اطلــع املدعــى عليــه‬\n\n                                                                                        ‫‪308‬‬\n\f      ‫عليهــا‪ ،‬صــادق املدعــى عليــه عليهــا وقــرر أنــه ليــس لديــه رخصــة قيــادة‬\n      ‫‪ ،‬صــدر احلكــم بإلــزام املدعــى عليــه بتســليم الورثــة املدعــن ديــة قتــل‬\n      ‫اخلطــأ‪ ،‬مت إفهــام املدعــى عليــه بــأن لــه الرجــوع علــى عاقلتــه وإفهامــه‬\n      ‫بكفــارة قتــل اخلطــأ‪ ،‬صــدر قــرار محكمــة االســتئناف مبكــة‬\n                                               ‫املكرمــة باملصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n      ‫أنــا‪ ..........‬القاضــي يف احملكمــة العامــة بالباحــة وبنــاء علــى املعاملــة‬\n      ‫احملالة لنا من فضيلة رئيس احملكمة العامة بالباحة برقم ‪33523501‬‬\n      ‫وتاريــخ ‪1433/08/13‬ه ـ املقيــدة باحملكمــة برقــم ‪331528230‬‬\n      ‫وتاريــخ ‪1433/08/13‬ه ـ واملعــادة إلينــا أخيــر برقــم ‪ 332187337‬يف‬\n      ‫‪1433/12/26‬ه ـ ويف يــوم الســبت املوافق‪1434/02/30‬ه ـ افتتحــت‬\n      ‫اجللســة األولــى الســاعة احلاديــة عشــرة وأربعــون دقيقــة للتأخــر يف‬\n      ‫اجللســة التــي ســبقتها وفيهــا حضــر ‪ ..........‬بنغالديشــي اجلنســية مبوجــب‬\n      ‫رخصــة اإلقامــة الصــادرة مــن جــوزات الباحــة برقــم‪( ....................‬ســارية‬\n      ‫املفعــول) بصفتــه وكيــا بالوكالــة الصــادرة مــن كاتــب عــدل دكا‬\n      ‫ال مــن والــدة‬‫ـ بنغالديــش برقــم ‪ 21‬وتاريــخ ‪2011/08/06‬م عــن ك ً‬\n      ‫املتوفــى وزوجــة املتوفــى واألخــت الشــقيقة للمتوفــى و األخ الشــقيق‬\n      ‫للمتوفــى واألخــت الشــقيقة للمتوفــى وهــم ورثــة املتوفــى وذلــك مبوجــب‬\n      ‫صــك حصــر اإلرث الصــادر مــن مجلــس االحتــاد مبحافظــة كيرانيغنــج‬\n      ‫التابعــة حملافظــة دكا ـ بنغالديــش برقــم ‪ 01‬وتاريــخ ‪2012/12/8‬م‬\n      ‫واملصدقــة مــن فــرع وزارة اخلارجيــة مبكــة املكرمــة برقــم بــدون‬\n\n‫‪309‬‬\n\f‫وتاريــخ ‪1434/02/16‬ه ـ ومــن فــرع وزارة العــدل مبكــة املكرمــة‬\n‫برقــم ‪ 344226‬وتاريــخ ‪1434/02/16‬ه ـ وقــد خــول للوكيــل احلاضــر‬\n‫يف وكالتــه تقــدمي الدعــوى والطلبــات أمــام احملاكــم وســحب واســتالم‬\n‫النقــود والتعويضــات اخلاصــة مبورثهــم املتوفــى علــي املتــويف بتاريــخ‬\n‫‪2011/04/26‬م فادعــى ( متحدثــا باللغــة العربيــة) علــى احلاضــر معــه‬\n‫‪ ..........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ..........‬قائــا يف‬\n‫دعــواه عليــه إنــه بتاريــخ ‪1432/05/23‬ه ـ كان مــورث موكلــي علــي‬\n‫يعمــل يف ســقي األشــجار علــى الطريــق العــام (طريــق امللــك عبــد العزيــز)‬\n‫عنــد إشــارة طريــق املنــدق وكان واقفــا خلــف صهريــج املــاء ‪ ،‬فتفاجــأ‬\n‫باملدعــى عليــه يدخــل علــى الطريــق العــام قادما من طريق املندق بســرعة‬\n‫علــى ســيارته مــن نــوع ‪ ......‬رقــم اللوحــة ‪ .....‬صنــع عــام ‪1985‬م والــذي‬\n‫اصطــدم مبــورث موكلــي ممــا أدى إلــى وفاتــه ‪ ،‬وقــد أديــن املدعــى عليه‬\n‫يف هــذا احلــادث بنســبة مائــة يف املائــة لــذا أطلــب احلكــم بإلــزام املدعــى‬\n‫عليــه بدفــع ديــة قتــل اخلطــأ ملوكلــي ورثــة املتوفــى وقدرهــا ثالثمائــة‬\n‫ألــف ريــال هــذه دعــواي وبعــرض مــا جــاء يف دعــواه علــى املدعــى عليــه‬\n‫أجــاب قائــا مــا جــاء يف دعــوى املدعــي كلــه صحيــح ‪ ،‬ولكــن ليــس‬\n‫لــدي اســتطاعة بــأداء كامــل املبلــغ كمــا أن احلــادث وقــع قبــل زيــادة‬\n‫مقــدار الديــة إلــى ثالثمائــة ألــف ريــال لــذا لســت مســتعدا بدفــع املبلــغ‬\n‫املدعــى بــه هــذه إجابتــي فجــرى االطــاع علــى أوراق املعاملــة فوجــدت‬\n‫بــن طياتهــا القــرار الشــرعي الصــادر مــن احملكمــة اجلزئيــة بالباحــة‬\n‫برقــم ‪ 2/66‬يف ‪1433/07/02‬ه ـ املتضمــن إثبــات إدانــة املدعــى عليــه‬\n‫مبســؤوليته عــن احلــادث الواقــع بتاريــخ ‪1432/5/23‬ه ـ والــذي دهــس‬\n‫فيــه الوافــد علــي بنســبة ‪ %100‬للحــق العــام وأفهــم بــأن عقوبتــه علــى ذلك‬\n\n\n                                                                                      ‫‪310‬‬\n\f      ‫راجعــة لولــي األمــر وقنــع بــه املدعــى عليــه انتهــى مضمونــه ‪ ،‬كمــا جــرى‬\n      ‫االطــاع علــى تقريــر اللجنــة املشــكلة بــإدارة املــرور مبوجــب خطــاب‬\n      ‫فضيلــة رئيــس احملكمــة اجلزئيــة بالباحــة املرفــق باملعاملــة لفــة رقــم‬\n      ‫‪ 42‬واملتضمــن تأييدهــا لتقريــر املــرور املــدان فيــه املدعــى عليــه بنســبة‬\n      ‫مائــة يف املائــة لألســباب التاليــة ‪1 :‬ـ قلــة االحتــراز وســيره بســرعة زائــدة‬\n      ‫علــى طريــق مزدحــم ‪2‬ـ دخولــه مــن شــارع فرعــي إلــى طريــق رئيســي‬\n      ‫دون التوقــف والتأكــد مــن ســامة الطريــق ‪،‬علمــا أنــه الحــظ وســائل‬\n      ‫الســامة املوجــودة يف الطريــق حســب مــا جــاء بأقوالــه مبلــف التحقيــق‬\n                                         ‫ص ‪ 5‬وهــذا إهمــال موجــب للمســؤولية ‪،‬‬\n      ‫‪-3‬عــدم مراعــاة األنظمــة حيــث جتاوز الســيارات على الطريق الرئيســي‬\n      ‫واجتــه إلــى أقصــى اليســار دون أخــذ احليطــة واحلــذر انتهــى نصهــا ‪،‬‬\n      ‫وبعرضهــا علــى املدعــى عليــه أجــاب قائــا مــا جــاء يف التقريــر صحيــح‬\n      ‫عــدا وجــود وســائل الســامة فلــم أشــاهد شــيئا منهــا هكــذا أجــاب‬\n      ‫فســألته كــم كانــت ســرعتك حــن دخلــت مــن الشــارع الفرعــي علــى‬\n      ‫الشــارع الرئيســي فأجــاب قائــا كانــت ســرعتي تقريبــا ‪ 90‬كــم يف‬\n      ‫الســاعة هكــذا أجــاب فســألته هــل كان لديــك رخصــة قيــادة فأجــاب‬\n      ‫قائــا لــم يكــن لــدي رخصــة قيــادة حينهــا هكــذا أجــاب ‪ ،‬فبنــاء علــى‬\n      ‫مــا تقــدم مــن الدعــوى واإلجابــة ومــا قــرره الطرفــان ‪ ،‬ومبــا أن املدعــى‬\n      ‫عليــه صــادق علــى صحــة دعــوى املدعــي وبنــاء علــى مــا جــاء يف القــرار‬\n      ‫الشــرعي املشــار إليــه أعــاه املتضمــن إثبــات إدانــة بنســبة ‪ %100‬للحــق‬\n      ‫العــام وبنــاء علــى مــا جــاء يف تقريــر جلنــة املــرور املــدون مضمونــه أعــاه‬\n      ‫ونظــرا لالقتنــاع مبســؤولية املدعــى عليــه للحــق اخلــاص بنفــس النســبة‬\n      ‫املــدان بهــا للحــق العــام نظــرا لألســباب املشــار إليــه يف التقريــر أعــاه ‪،‬‬\n\n\n‫‪311‬‬\n\f‫وبنــاء علــى قــرار الهيئــة العامــة للمحكمــة العليــا رقــم ‪ 2‬وتاريــخ‬\n‫‪1431/7/14‬ه ـ املوافــق عليــه مــن قبــل مجلــس الــوزراء برقــم‪ 43108‬يف‬\n‫‪1432/10/20‬ه ـ املعمــم علــى احملاكــم بخطــاب معالــي رئيــس املجلــس‬\n‫األعلــى للقضــاء برقــم ‪/192‬ت وتاريــخ ‪1432/10/9‬ه ـ املتضمــن إعــادة‬\n‫تقييــم الديــات بحيــث تكــون ديــة القتــل اخلطــا ثالثمائــة ألــف ريــال‬\n‫ســعودي واملتضمــن كذلــك أن هــذا التقديــر يســري علــى كل حالــة‬\n‫لــم يحكــم فيهــا قبــل العمــل بــه ‪ ،‬ولــكل مــا تقــدم فقــد حكمــت‬\n‫بإلــزام املدعــى عليــه بتســليم املدعــي وكالــة مبلــغ ديــة قتــل اخلطــأ‬\n‫وقــدره ثالثمائــة ألــف ريــال (‪ 300000‬ريــال) ولــه الرجــوع علــى العاقلــة‬\n‫ومطالبتهــم بــه ‪ ،‬وأفهمتــه أن عليــه كفــارة قتــل اخلطــأ وهــي حتريــر‬\n‫رقبــة مؤمنــة فــإن لــم يجــد فصيــام شــهرين متتابعــن ‪ ،‬واملبلــغ احملكــوم‬\n‫بــه لــأم منــه خمســون ألــف ريال(‪50000‬ريــال) ‪ ،‬وللزوجــة منــه خمســة‬\n‫وســبعون ألــف ريــال (‪ 75000‬ريــال) ‪ ،‬والباقــي لإلخــوة األشــقاء للذكــر‬\n‫مثــل حــظ األنثيــن بحيــث يكــون نصيــب الذكــر ســبعة وثمانــون ألفــا‬\n‫وخمســمائة ريــال (‪ 87500‬ريــال)‪ ،‬ونصيــب كل أنثــى ثالثــة وأربعــون‬\n‫ألفــا وســبعمائة وخمســون ريــاال (‪ 43750‬ريــال )‪ ،‬وبعــرض احلكــم علــى‬\n‫املدعــي وكالــة واملدعــى عليــه قــرر املدعــي وكالــة قناعتــه بــه وقــرر‬\n‫املدعــى عليــه اعتراضــه عليــه وطلــب رفــع احلكــم حملكمــة االســتئناف‬\n‫بــدون الئحــة اعتراضيــة فأمــرت بتنظيــم صــك بذلــك ورفعهــا حملكمــة‬\n‫االســتئناف ليقــرر أصحــاب الفضيلــة قضــاة االســتئناف الــرأي فيهــا‬\n‫وختمــت اجللســة الثانيــة عشــرة والنصــف ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/30‬هـ‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم االثنــن املوافــق ‪1434/04/08‬ه ـ‬\n\n\n                                                                                  ‫‪312‬‬\n\f      ‫افتتحــت اجللســة الســاعة الثانيــة عشــرة هــذا وقــد عــادت املعاملــة‬\n      ‫مــن محكمــة االســتئناف مبكــة املكرمــة برقــم ‪ 34648617‬يف‬\n      ‫‪1434/03/29‬ه ـ وبرفقهــا قــرار التصديــق الصــادر مــن الدائــرة اجلزائية‬\n      ‫اخلامســة مبحكمــة االســتئناف برقــم ‪ 34167954‬يف ‪1434/03/22‬ه ـ‬\n      ‫واملتضمــن بعــد املقدمــة مــا نصــه « وبدراســة الصــك وصــورة ضبطــه‬\n      ‫قررنــا املوافقــة علــى احلكــم ‪ ،‬وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n      ‫محمــد وآلــه وصحبــه وســلم قاضــي اســتئناف ‪ ..........‬موقــع علــى األصــل‬\n      ‫وموافــق علــى احلكــم ومجــاز ‪ ،‬قاضــي اســتئناف ‪ ..........‬ختــم وتوقيــع‬\n      ‫‪ ،‬رئيــس اســتئناف د‪ .......... .‬ختــم وتوقيــع « انتهــى نصــه وقــد ظهــر‬\n      ‫مبضمونــه علــى الصــك ‪ ،‬وللعلــم جــرى حتريــره وصلــى اهلل علــى نبينــا‬\n                      ‫محمــد وآلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/04/08‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلامســة مبحكمــة اإلســتئناف‬\n      ‫يف منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامة بالباحة برقــم ‪332187337‬وتاريخ ‪1434/3/4‬‬\n      ‫ه ـ املرفــق بهــا الصــك رقــم ‪3452403‬وتاريخ‪1434/3/1‬ه ـ الصــادر‬\n      ‫مــن فضيلــة الشــيخ ‪ /‬القاضــي باحملكمــة العامــة بالباحــة املتضمــن‬\n      ‫دعــوى‪ ........../‬بنغالديشــي اجلنســية وكالــة ضــد ‪ ........../‬ســعودي‬\n      ‫اجلنســية يف مطالبــة بديــة‪ ،‬احملكــوم فيــه مبــا دون بباطــن القــرار ‪،‬‬\n      ‫وبدراســة الصــك وصــورة ضبطــه قررنــا املوافقــة علــى احلكــم ‪ ،‬واهلل‬\n             ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪313‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":308,"source_page_end":313,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3b313e513ad06f0b8f66792bce47cb1abfb38ebfc1eaab557868fd06b30de59b","normalized_text_hash":"9fa1d89544d44b56fa8a78c372d2adb95be374f2f549fd6bb628e5a969ba0aa8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p308-3452403"},{"id":"ec2ce2f2-2acc-5476-9ded-f556b268e045","document_type":"judgment","category":"judicial","subcategory":"general","title":"دية-مطالبة بدية مورث -استئجار استراحة بدون عقد -استئجار مسبح والغرق فيه لعدم معرفته السباحة وعدم وجود ترخيص ولعدم توفر وسائل السامة -دفع املدعى عليه بأنه بالغ عاقل يدرك عواقب األمور -تقرير الدفاع املدني -تنازل األم عن نصيبها يف الدية -احلكم برد الدعوى .","document_number":"3445460","case_number":"33546351","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/24","year":"1434","subject":"دية-مطالبة بدية مورث -استئجار استراحة بدون عقد -استئجار مسبح والغرق فيه لعدم معرفته السباحة وعدم وجود ترخيص ولعدم توفر وسائل السامة -دفع املدعى عليه بأنه بالغ عاقل يدرك عواقب األمور -تقرير الدفاع املدني -تنازل األم عن نصيبها يف الدية -احلكم برد الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/2/24 :‬هـ َر ْق ُم‬\n                         ‫ُ‬                ‫َر ْق ُم َّ‬\n                             ‫الص ِّك‪3445460 :‬‬\n                              ‫الدعوى‪33546351 :‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                    ‫‪ 34180375‬تاريخه‪1434/4/7 :‬هـ‬\n\n\n   ‫دية‪-‬مطالبــة بديــة مــورث‪ -‬اســتئجار اســتراحة بــدون عقــد‪ -‬اســتئجار‬\n   ‫مســبح والغــرق فيــه لعــدم معرفتــه الســباحة وعــدم وجــود ترخيــص‬\n   ‫ولعــدم توفــر وســائل الســامة‪ -‬دفــع املدعــى عليــه بأنــه بالــغ عاقــل‬\n   ‫يــدرك عواقــب األمــور‪ -‬تقريــر الدفــاع املدنــي‪ -‬تنــازل األم عــن نصيبهــا‬\n                                             ‫يف الديــة‪ -‬احلكــم بــرد الدعــوى ‪.‬‬\n\n\n\n\n   ‫قــول ابــن قدامــة ‪ « :‬فــإن حفــر إنســان يف ملكــه بئــرا فوقــع فيهــا إنســان أو‬\n   ‫دابــة فهلــك بــه وكان الداخــل دخــل بغيــر إذنه فال ضمــان على احلافر‬\n   ‫ألنــه ال عــدوان منــه وإن دخــل بإذنــه والبئــر بينــة مكشــوفة والداخــل‬\n   ‫بصيــر يبصرهــا فــا ضمــان أيضــا ألن الواقــع هــو الــذي أهلــك نفســه‬\n   ‫فأشــبه مــا لــو قــدم إليــه ســيف فقتــل بــه نفســه » أ‪.‬ه ـ املغنــي (‪،)427/8‬‬\n                                 ‫وينظــر يف هــذا املعنــى كشــاف القنــاع (‪.)7/6‬‬\n\n\n\n\n   ‫تقــدم املدعــي بدعــوى ضــد مالــك اســتراحة بأنــه أجــر ابنــه وأصحابــه‬\n   ‫مســبحه باســتراحته فنــزل بهــا وغــرق لكونــه ال يجيــد الســباحة‪ ،‬وألنــه‬\n   ‫ال ميلــك ترخيصــا بتأجيــر املســبح ولعــدم توفــر وســائل الســامة وال منقــذ‬\n   ‫فقــد طلــب إلــزام املدعــى عليــه بدفــع نصيبــه مــن ديــة ابنــه لتنــازل الوريث‬\n\n                                                                                           ‫‪314‬‬\n\f      ‫اآلخــر والدتــه عــن نصيبهــا‪ ،‬أقــر املدعــى عليــه بــأن ابــن املدعــي غــرق يف‬\n      ‫مســبح اســتراحته إال أنــه أنكــر تأجيــره املســبح عليــه وأن ابنــه وبقيــة‬\n      ‫أصحابــه رغبــوا يف اســتئجاره واســتعجلوا ودخلــوا قبــل إبــرام العقــد‬\n      ‫واإلذن لهــم بذلــك كمــا أنكــر دعــوى املدعــي بعــدم وجــود وســائل‬\n      ‫ســامة ودفــع بــأن ابنــه بالــغ وعاقــل وأنــه ال يؤجــر املســبح عــادة إال بعدمــا‬\n      ‫يقــر املســتأجر بأنــه يجيــد الســباحة وحتملــه املســؤولية جتــاه مــا ينجــم‬\n      ‫مــن حــوادث غــرق وطلــب رد دعــواه‪ ،‬جــرى االطــاع علــى تقريــر الدفــاع‬\n      ‫املدنــي واملتضمــن بــأن حادثــة الغــرق عرضــي وال توجــد تهمــة جنائيــة وأن‬\n      ‫ســببه عــدم إجادتــه للســباحة وإقدامــه واحلمــاس مــع رفقائــه والنــزول‬\n      ‫للمســبح دون إدراك عواقــب وخطــورة ذلــك وعــدم تأمــن صاحــب‬\n      ‫املســبح وســائل الســامة ووضــع قيــود الســامة ملرتاديــه‪ ،‬عليــه وإلقــرار‬\n      ‫املدعــي بــأن ابنــه بالــغ عاقــل واســتأجر املســبح مــع زمالئــه ونــزل إلــى‬\n      ‫املســبح للســباحة فغــرق لعــدم إجادتــه للســباحة فهــو الــذي أهلــك نفســه‬\n      ‫وال يوجــد ســبب يوجــب تضمــن املدعــى عليــه ألن املتوفــى ســبح بإرادتــه‬\n      ‫واختيــاره وكان عليــه أال يقــدم علــى الســباحة إال وهــو يجيدهــا قــال‬\n      ‫ابــن قدامــة «فــإن حفــر إنســان يف ملكــه بئــرا فوقــع فيهــا إنســان أو دابــة‬\n      ‫فهلــك بــه وكان الداخــل دخــل بغيــر إذنــه فــا ضمــان علــى احلافــر ألنــه‬\n      ‫ال عــدوان منــه وإن دخــل بإذنــه والبئــر بينــة مكشــوفة والداخــل بصيــر‬\n      ‫يبصرهــا فــا ضمــان أيضــا ألن الواقــع هــو الــذي أهلــك نفســه فأشــبه‬\n      ‫مــا لــو قــدم إليــه ســيف فقتــل بــه نفســه» انتهــى مــن املغنــي (‪)427/8‬‬\n      ‫وينظــر يف هــذا املعنــى كشــاف القنــاع (‪ )7/6‬وملــا تقــدم كلــه فقــد‬\n      ‫قــررت احملكمــة رد دعــوى املدعــي ضــد املدعــى عليــه لعــدم ثبــوت مــا‬\n      ‫يوجــب حتميلــه شــيئا مــن الديــة‪ ،‬اعتــرض املدعــي علــى احلكــم وأفهــم‬\n\n\n‫‪315‬‬\n\f                  ‫بالتعليمــات‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ................‬القاضــي يف احملكمــة‬\n‫العامــة بعنيــزة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة بعنيــزة برقــم ‪ 33546351‬وتاريــخ ‪1433/8/25‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 331595986‬وتاريــخ ‪1433/08/25‬ه ـ‬\n‫بشــأن دعــوى ‪ ...............‬ضــد ‪ ...............‬يف دعــوى ديــة افتتحــت اجللســة‬\n‫يف الوقــت احملــدد لســماعها ولــم يحضــر املدعــي وال مــن ميثلــه ولــم‬\n‫يقــدم عــذرا وحضــر املدعــى عليــه ‪ ...............‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ ...............‬وانتهــى وقــت اجللســة دون حضــور املدعــي‬\n‫ولذلــك فقــد شــطبت الدعــوى للمــرة األولــى ويف جلســة أخــرى حضــر‬\n‫املدعــي ‪ ...............‬واعتــذر لغيابــه عــن اجللســة املاضيــة بســبب لبــس يف‬\n‫املوعــد لديــه وطلــب حتديــد جلســة قادمــة ملواصلــة النظــر يف دعــواه‬\n‫ضــد ‪ ...............‬بشــأن ديــة ابنــه ‪ ...............‬املتوفــى يف ‪1433/5/24‬ه ـ‬\n‫واملنحصــر إرثــه يف والــده ‪ ...............‬ووالدتــه ‪ ...............‬ولــه جمــع مــن‬\n‫االخــوة يحجبــون األم مــن الثلــث إلــى الســدس مبوجــب صــك حصــر‬\n‫الورثــة الصــادر مــن هــذه احملكمــة برقــم ‪ 3438105‬يف ‪1434/2/16‬ه ـ‬\n‫وقــد جــرى االطــاع علــى صــك حصــر الورثــة فوجدتــه كمــا ذكــر‬\n‫وســألت املدعــي عــن والــدة املتوفــى فقــال إنهــا متنازلــة عــن نصيبهــا مــن‬\n‫الديــة وال ترغــب مواصلــة الدعــوى هكــذا قــرر وقــد حضــرت يف هــذه‬\n‫اجللســة والــدة املتوفــى املذكــور ‪ ...............‬ســعودية اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ ...............‬املعــرف بهــا مــن قبــل ‪ ...............‬ســعودي‬\n\n                                                                                           ‫‪316‬‬\n\f      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ..................‬وقــررت قائلــة إننــي‬\n      ‫متنازلــة عــن نصيبــي مــن ديــة ابنــي املتوفــى املذكــور ‪ ...............‬الــذي‬\n      ‫تــويف غرقــا يف مســبح اســتراحة املدعــى عليــه ‪ ...............‬فــا أطالــب‬\n      ‫املدعــى عليــه وال عاقلتــه بشــيء مــن ديــة ابنــي املذكــور ال حاضــرا وال‬\n      ‫مســتقبال هكــذا قــررت وجــرى إحلاقــه حتــى ال يخفــى ويف جلســة أخــرى‬\n      ‫حضــر املدعــي ‪ ...............‬وحضــر حلضــوره املدعــى عليــه‪...............‬‬\n      ‫ســعودي اجلنســي مبوجــب الســجل املدنــي رقــم ‪ ...............‬وحــرر املدعــي‬\n      ‫دعــواه قائــا إنــه بتاريــخ ‪1433/5/24‬ه ـ تــويف ابنــي ‪ ...............‬وكانــت‬\n      ‫وفاتــه بســبب غرقــه يــوم الثالثــاء املوافــق ‪1433/5/18‬ه ـ يف مســبح يقــع‬\n      ‫يف اســتراحة املدعــى عليــه يف حــي ‪ ...............‬بعنيــزة الســاعة الرابعــة‬\n      ‫عصــرا حيــث ذهــب ابنــي املتوفــى إلــى االســتراحة املذكــورة برفقــة‬\n      ‫بعــض أصحابــه واســتأجروا مســبح اســتراحة املدعــى عليــه ونــزل ابنــي‬\n      ‫للســباحة وغــرق يف املســبح لعــدم إجادتــه الســباحة وإلهمــال املدعــى‬\n      ‫عليــه بعــدم حصولــه علــى ترخيــص للمســبح وعــدم وجــود منقــذ وعــدم‬\n      ‫وجــود وســائل ســامة فإنــي أطلــب احلكــم علــى املدعــى عليــه بدفــع‬\n      ‫نصيبــي مــن ديــة ابنــي وقــدره مائتــان وخمســون ألــف ريــال بعــد خصــم‬\n      ‫ســدس والــدة املتوفــى هــذه دعــواي وبســؤال املدعــى عليــه عــن دعــوى‬\n      ‫املدعــي أجــاب بقولــه أمــا مــا ذكــره املدعــي مــن أن ابنــه املذكــور تــويف‬\n      ‫بســبب غرقــه يف املســبح اخلــاص بــي املوجــود يف اســتراحتي املذكــورة‬\n      ‫فهــذا صحيــح وأمــا مــا ذكــره مــن أن ابنــه اســتأجر املســبح فهــذا ليــس‬\n      ‫بصحيــح والصحيــح أن ابنــه وأصحابــه كانــوا يريــدون اســتئجار املســبح‬\n      ‫ولــم يوقعــوا العقــد واســتعجلوا ودخلــوا املســبح بــدون عقــد ونتــج عنــه‬\n      ‫غــرق ابــن املدعــى عليــه يف املســبح وال أعلــم عــن تفاصيــل غرقــه لعــدم‬\n\n\n‫‪317‬‬\n\f‫وجــودي يف املســبح علمــا بأنــه يوجــد يف املســبح وســائل ســامة كمــا‬\n‫أننــا ال نؤجــر إال البالــغ العاقــل الــذي يحمــل بطاقــة أحــوال علــى أن‬\n‫يتعهــد بإجادتــه الســباحة ويتحمــل مســؤولية املســبح مــدة العقــد مبوجــب‬\n‫عقــد يوقعــه وبالنســبة البــن املدعــي فإنــه بالــغ عاقــل هــذا أوال وأمــا ثانيــا‬\n‫فإنــه دخــل املســبح بــدون عقــد ولذلــك فإنــي أطلــب رد دعــوى املدعــي‬\n‫هكــذا أجــاب املدعــى عليــه وقــد ســألت املدعــي عــن ابنــه هــل هــو بالــغ‬\n‫عاقــل عندمــا غــرق فأجــاب بقولــه نعــم ابنــي بالــغ عاقــل عندمــا غــرق‬\n‫هكــذا أجــاب املدعــي وقــد اطلعــت علــى صــورة بطاقــة ابــن املدعــي‬\n‫املتوفــى املرفقــة يف املعاملــة فوجــدت أن ميــاده يف ‪1417/6/20‬ه ـ وقــد‬\n‫تصفحــت املعاملــة فوجــدت فيهــا التقريــر املفصــل الصــادر مــن الدفــاع‬\n‫املدنــي بعنيــزة عــن حــادث غــرق ابــن املدعــي ونــص احلاجــة منــه (اتضــح‬\n‫لنــا مــن خــال إجــراءات التحقيــق واملعاينــة ملوقــع حــادث غــرق الشــاب‬\n‫‪ ......................‬يف مســبح اســتراحة ‪ .....‬يف املنطقــة العميقــة عرضيــا‬\n‫دون تســبب أحــد بإغراقــه وأن أســباب الغــرق نــاجت عــن عــدم إجادتــه‬\n‫للســباحة وإقدامــه واحلمــاس مــع رفقائــه والنــزول للمســبح دون إدراك‬\n‫عواقــب خطــورة ذلــك وعــدم تأمــن صاحــب املســبح وســائل الســامة‬\n‫ووضــع قيــود الســامة ملرتــادي املســبح معــد التقريــر رئيــس رقبــاء‬\n‫‪ .............‬توقيعــه مديــر شــعبة العمليــات عقيــد ‪ ..........‬توقيعــه مديــر‬\n‫الدفــاع املدنــي ‪ ................‬توقيعــه انتهــى ) فبنــاء علــى مــا تقــدم من دعوى‬\n‫املدعــي وجــواب املدعــى عليــه ونظــرا إلــى أن املدعــي هــو والــد املتوفــى‬\n‫املذكــور مبوجــب صــك حصــر الورثــة املرصــود ســابقا وال يشــاركه يف‬\n‫امليــراث ســوى والــدة املتوفــى املتنازلــة عــن نصيبهــا مــن الديــة ونظــرا إلــى‬\n‫أن املدعــي ذكــر فيدعــواه أن ابنــه بالــغ عاقــل وأنــه اســتأجر املســبح‬\n\n\n                                                                                          ‫‪318‬‬\n\f      ‫مــع زمالئــه ونــزل إلــى املســبح للســباحة فغــرق لعــدم إجادتــه للســباحة‬\n      ‫ومــن خــال هــذه الوقائــع الثابتــة بادعــاء املدعــي والــد املتوفــى يتبــن أن‬\n      ‫املتوفــى نــزل للســباحة بإرادتــه وهــو بالــغ عاقــل فهــو الــذي أهلــك نفســه‬\n      ‫وال يوجــد ســبب يوجــب تضمــن املدعــى عليــه ألن املتوفــى ســبح بإرادتــه‬\n      ‫واختيــاره وكان عليــه أال يقــدم علــى الســباحة إال وهــو يجيدهــا قــال‬\n      ‫ابــن قدامــة فــإن حفــر إنســان يف ملكــه بئــرا فوقــع فيهــا إنســان أو دابــة‬\n      ‫فهلــك بــه وكان الداخــل دخــل بغيــر إذنــه فــا ضمــان علــى احلافــر ألنــه‬\n      ‫ال عــدوان منــه وإن دخــل بإذنــه والبئــر بينــة مكشــوفة والداخــل بصيــر‬\n      ‫يبصرهــا فــا ضمــان أيضــا ألن الواقــع هــو الــذي أهلــك نفســه فأشــبه مــا‬\n      ‫لــو قــدم إليــه ســيف فقتــل بــه نفســه انتهى مــن املغنــي (‪ )427/8‬وينظر يف‬\n      ‫هــذا املعنــى كشــاف القنــاع (‪ )7/6‬وملــا تقــدم كلــه فقــد رددت دعــوى‬\n      ‫املدعــي ضــد املدعــى عليــه لعــدم ثبــوت مــا يوجــب حتميلــه شــيئا مــن‬\n      ‫الديــة وبذلــك حكمــت وبعــرض احلكــم علــى املدعــي قــرر عــدم القناعة‬\n      ‫بــه وطلــب رفــع احلكــم حملكمــة االســتئناف بــدون الئحــة اعتراضيــة‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n      ‫حــرر يف ‪1434/02/24‬ه ــاحلمد هلل وحــده وبعــد فلــدي أنــا ‪................‬‬\n      ‫القاضــي يف احملكمــة العامــة بعنيــزة وبنــاء علــى املعاملــة احملالــة لنــا‬\n      ‫مــن فضيلــة رئيــس احملكمــة العامــة بعنيــزة برقــم ‪ 33546351‬وتاريــخ‬\n      ‫‪1433/08/25‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331595986‬وتاريــخ‬\n      ‫‪1433/08/25‬ه ـ ففــي يــوم األحــد املوافــق‪ 1434/04/21‬ه ـ افتتحــت‬\n      ‫اجللســة وقــد عــادت املعاملــة مــن محكمــة االســتئناف بالقصيــم برقــم‬\n      ‫‪ 34672125‬يف ‪1434/4/15‬ه ـ وبرفقهــا قــرار محكمــة االســتئناف‬\n      ‫بالقصيــم رقــم ‪ 34180375‬يف ‪1434/4/7‬ه ـ املتضمــن مــا نصــه بعــد‬\n\n\n‫‪319‬‬\n\f‫املقدمــة وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة لــم يظهــر‬\n‫لألكثريــة مــا يوجــب املالحظــة علــى مــا حكــم بــه فضيلتــه وصلــى اهلل‬\n‫وســلم علــى نبينــا محمــد وآلــه وصحبــه أجمعــن و للمعلوميــة حــرر يف‬\n                                                                          ‫‪1433/4/21‬ه ـ ‪.‬‬\n‫الـحـم ــد هلل وحـ ــده وبـعـد‪...‬فـق ــد اطَّ ـلـع ــنا نحــن قـض ــاة الـدائ ــرة الـثـانـي ــة‬\n‫لـتـدقـي ــق الـقـضـايـ ــا الـجـزائـي ــة بـمـحـكـم ــة االسـتـئـن ــاف بـمـنـطـق ــة‬\n‫الـقـصـي ــم عـل ــى الـمـعـامـل ــة الـ ــواردة م ــن فـضـيـل ــة رئـي ــس الـمـحـكـم ــة‬\n‫الـعـام ــة بـمحافـظ ــة عـنـي ــزة بـرقـ ــم (‪ )34354603‬يف ‪1434/3/15‬هــ؛‬\n‫املرفــق بهــا الصــك رقــم (‪ )3445460‬يف ‪1434/2/24‬هــ؛ الصــادر‬\n‫مــن فضيلــة الشــيخ‪ ...............‬القاضــي يف احملكمــة؛ اخلــاص بدعــوى‬\n‫‪ .................‬ضــد‪ ...............‬بشــأن مطالبــة املدعــي بنصيبــه مــن ديــة ابنــه‬\n‫املتوفــى غرق ـ ًا يف مســبح اســتراحة املدعــى عليــه‪ ،‬وقــد تضمــن الصــك‬\n‫حكــم فضيلتــه بــرد دعــوى املدعــي ضــد املدعــى عليــه لعــدم ثبــوت مــا‬\n‫املفصــل فيــه؛ وبدراســة‬   ‫َّ‬     ‫يوجــب حتميلــه شــيئ ًا مــن الديــة؛ علــى النحــو‬\n‫الصــك وصــورة ضبطــه وأوراق املعاملــة؛ لــم يظهــر لألكثريــة مــا يوجــب‬\n‫املالحظــة علــى مــا حكــم بــه فضيلتــه‪ ،‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى‬\n                                                 ‫نبينــا محمــد وآلــه وصحبــه وســلم‪...‬‬\n\n\n\n\n                                                                                                   ‫‪320‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":314,"source_page_end":320,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5de15b65a838a628189c9768995892e0eb4462a1ebd7eafed55e00fff70aa292","normalized_text_hash":"6128ab2ceb391d32f4f4ec4bb2f53fdef5b31042ab4504b9de53eff934bda079","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p314-3445460"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

